(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ta"] = {"ui":{"skip":"உள்ளடக்கத்துக்குச் செல்","back":"← AI-gile-க்குத் திரும்பு","lang.button":"மொழி: {name}","lang.dialog":"மொழியைத் தேர்ந்தெடுங்கள்","lang.search":"மொழிகளைத் தேடுங்கள்","lang.none":"பொருந்தும் மொழி இல்லை","lang.notYet":"{name} இன்னும் மொழிபெயர்க்கப்படவில்லை","theme.aria":"தீமை மாற்று: ஒளி, இருண்ட அல்லது கருப்பு","theme.toLight":"ஒளி தீமுக்கு மாற்று","theme.toDark":"இருண்ட தீமுக்கு மாற்று","theme.toBlack":"கருப்பு தீமுக்கு மாற்று (உண்மையான கருப்பு, OLED திரைகளுக்கு இதமானது)","words.underline":"பக்கத்தில் இந்தச் சொற்களுக்கு அடிக்கோடிடு","words.underlineHelp":"புள்ளிக்கோடிட்ட சொல்லின் மேல் சுட்டியை வையுங்கள் அல்லது தட்டுங்கள், அதன் பொருள் தெரியும்.","words.col.todo":"இப்போதைக்குத் தேர்ந்தெடுத்த கார்டுகள்: குழு அடுத்து இவற்றில் தொடங்கும்.","words.col.doing":"ஒரு AI இப்போது இந்த கார்டில் வேலை செய்கிறது.","words.col.review":"ஒரு AI வேலையை முடித்தது; உங்களிடம் வருவதற்கு முன் இன்னொரு AI அதைச் சரிபார்க்கும்.","words.col.verify":"உங்களுக்காகக் காத்திருக்கிறது: முயன்று பார்த்து, வேலை செய்கிறதா என்று சொல்லுங்கள்.","words.col.team":"உங்கள் குறிப்புகள் அல்லது பதில்கள், குழு எடுத்துக்கொள்ளக் காத்திருக்கின்றன.","words.col.done":"முடிந்து ஏற்றுக்கொள்ளப்பட்டது.","index.title":"AI-gile: உங்கள் AI டெவ் டீம், ஒரே போர்டில்","index.description":"AI-gile என்பது AI கோடிங் டீம்களுக்கான கான்பன் போர்டு. நீங்கள் தூங்கும்போது அவர்கள் வேலை செய்கிறார்கள்; நீங்கள் முடிவு செய்ய, சோதிக்க, ஏற்க ஒரு சிறிய குவியல் மட்டும் கிடைக்கும்.","hero.logoAlt":"AI-gile போர்டு ஐகான்","hero.h1.html":"உங்கள் AI டெவ் டீம், ஒரே&nbsp;போர்டில்.","hero.alpha":"🐣 மூடிய ப்ரீ-ஆல்பா","hero.alphaTitle":"ஆரம்ப நிலை, முடியாதது: முயற்சிப்பதற்கு நன்றி!","hero.lede":"நீங்கள் தூங்கும்போது அவர்கள் உருவாக்குகிறார்கள். காலையில் ஒரு சிறிய குவியல்: சில கேள்விகள், சோதிக்க சில விஷயங்கள், ஒன்றிரண்டு ஊதா வைரங்கள். கிளிக் செய்யுங்கள், ஏற்றுக்கொள்ளுங்கள், மீண்டும் காபிக்குத் திரும்புங்கள்.","dl.windows":"Windows ஆப்","dl.browser":"உலாவியில் இயக்குங்கள்","dl.messenger":"📱 உங்கள் போனுக்கான Messenger","dl.soon":"விரைவில் வருகிறது","dl.notify":"🔔 திறக்கும்போது சொல்லுங்கள்","dl.notifySmall":"ஆல்பா அல்லது பீட்டா","hero.secondary":"அஜைல்தான், ஆனால் டீமுக்கு ஸ்டாண்ட்-அப் காபி தேவையே இல்லை. (இருந்தாலும் ஸ்டாண்ட்-அப் நடத்துவார்கள்.)","pitch.h2":"AI-gile, நீங்கள் விரும்பும் எத்தனை சொற்களிலும்","pitch.lede":"ஒரு சொல்லிலிருந்து 144 வரை நீளத்தைத் தேர்ந்தெடுங்கள். ஒவ்வொரு நீளமும் அந்த அளவுக்காக எழுதப்பட்ட தனி விளக்கம். ஸ்லைடரை இழுக்கவும் அல்லது அம்புக்குறி விசைகளைப் பயன்படுத்தவும்.","pitch.rangeLabel":"சொற்களில் நீளம்","pitch.dice":"🎲 இன்னொரு பதிப்பு","pitch.words.one":"{n} சொல்","pitch.words.other":"{n} சொற்கள்","pitch.letters.one":"{n} எழுத்து","pitch.letters.other":"{n} எழுத்துகள்","pitch.chars.one":"{n} குறி","pitch.chars.other":"{n} குறிகள்","count.line.html.one":"இப்போது போர்டில் {n} கார்டு","count.line.html.other":"இப்போது போர்டில் {n} கார்டுகள்","people.humans.html.one":"👥 {n} மனிதர்","people.humans.html.other":"👥 {n} மனிதர்கள்","people.agents.html.one":"🤖 {n} ஏஜென்ட்","people.agents.html.other":"🤖 {n} ஏஜென்ட்கள்","people.working.html.one":"⚡ இப்போது {n} வேலையில்","people.working.html.other":"⚡ இப்போது {n} வேலையில்","pre.title":"AI-gile: ஏதோ ஒன்று உருவாகிறது","pre.description":"இங்கே ஏதோ ஒன்று உருவாகிறது: நீங்கள் கேட்பதை AI அணிகள் உருவாக்கி, அதே நேரத்தில் உங்களுக்குக் கற்றுத்தரும் ஒரு போர்டு. இப்போதைக்கு நண்பர்களுடன் மூடிய ப்ரீ-ஆல்பா.","pre.h1":"இங்கே ஏதோ ஒன்று உருவாகிறது. 🤫","pre.line":"நீங்கள் கேட்பதை AI அணிகள் உருவாக்கி, அதே நேரத்தில் உங்களுக்குக் கற்றுத்தரும் ஒரு போர்டு. இப்போதைக்கு நண்பர்களுடன் மூடிய ப்ரீ-ஆல்பா.","pre.btn":"🔔 திறக்கும்போது சொல்லுங்கள்","pre.peek":"கண்ணாடிக்குப் பின்னால்: உண்மையான போர்டு, நேரலையில். ஒவ்வொரு அட்டையும் ஒரு வண்ணப் பட்டை.","pre.peekFake":"கண்ணாடிக்குப் பின்னால்: வேலை செய்யும் ஒரு போர்டு இப்படித்தான் இருக்கும்.","pre.night":"🌙 இரவுக் காவலர் பொறுப்பில் இருக்கிறார் · 😴 மனிதர் ஓய்வெடுக்கிறார்","features.aria":"இது என்ன செய்கிறது","f.pile.h":"உங்களுக்கு ஒரே குவியல்","f.pile.html":"<b>உங்களுக்கு</b> என்பது எல்லா ப்ராஜெக்ட்களிலும் உங்களுக்காகக் காத்திருக்கும் அனைத்தையும் வைத்திருக்கும்: கேள்விகள், சோதிக்க வேண்டியவை, மனிதர் மட்டுமே செய்யக்கூடிய வேலைகள். உங்கள் வரிசை அடுத்தது என்ன, எவ்வளவு நேரம் ஆகும் என்று சொல்லும்.","f.sleep.h":"நீங்கள் தூங்கும்போது வேலை செய்யும் டீம்கள்","f.sleep.p":"ஒவ்வொரு ப்ராஜெக்டுக்கும் ஒரு லீடும் AI ஏஜென்ட்களின் டீமும் உண்டு. கார்டில் கருத்து எழுதினால் டீம் எழுந்து, வேலையை முடித்து, களைத்த மனிதரும் பின்பற்றக்கூடிய படிகளுடன் திருப்பித் தரும்.","f.tester.h":"AI டெஸ்டர் முதலில் சரிபார்க்கிறார்","f.tester.p":"எதுவும் உங்களிடம் வருவதற்கு முன், டெஸ்டர் ஆப்பின் நகலில் படிகளைப் பின்பற்றி, தான் பார்த்ததை ஸ்கிரீன்ஷாட்டுடன் காட்டுவார். தேர்ச்சி பெற்றவற்றை புரட்டிப் பார்த்து ஒரே கிளிக்கில் ஏற்கலாம்.","f.proof.h":"வாக்குறுதி அல்ல, ஆதாரம்","f.proof.p":"ஒவ்வொரு ஒப்படைப்பும் என்ன மாறியது என்று காட்டும்: கோப்புகள், வேறுபாடு, ஸ்கிரீன்ஷாட்கள். முடிந்ததா என்று பார்க்க ஒவ்வொரு ஆப்பையும் திறக்க வேண்டியதில்லை.","f.chat.h":"உங்கள் லீடுகளுடன் அரட்டை","f.chat.p":"Discord போன்ற பக்கப்பட்டை: ஒரு ப்ராஜெக்டுக்கு ஒரு ஐகான், உங்களுக்குத் தேவையானவற்றுக்கு ஊதா வைரங்கள். லீடுக்கு ஒரு யோசனையை அனுப்புங்கள்; அவர் அதை கார்டுகளாகவும் திட்டமாகவும் மாற்றி, ✅ தொடங்கு பொத்தானுடன் தருவார்.","f.tidy.h":"தன்னைத் தானே ஒழுங்குபடுத்திக் கொள்கிறது","f.tidy.p":"தொடர்புடைய கார்டுகள் ஒன்றாக இணையும், குழப்பமான தலைப்புகள் சரிசெய்யப்படும், டோக்கன் சோதனை கோடை எளிமையாக வைக்கும். மாறிமாறிப் பார்க்க குறைவானவை, யோசிக்க குறைவானவை.","f.private.h":"உங்களுடையது, உங்கள் கணினியில்","f.private.li1":"போர்டு உங்கள் சொந்த கணினியில் இயங்கி உங்களுக்கு மட்டுமே பதிலளிக்கும்.","f.private.li2":"மனிதர்களுக்கிடையேயான தனிப்பட்ட செய்திகள் தொடக்கம் முதல் இறுதி வரை குறியாக்கம் செய்யப்படுகின்றன.","f.private.li3":"கணக்குகள் இல்லை, டிராக்கர்கள் இல்லை, குக்கீகள் இல்லை.","f.lang.h":"உங்கள் மொழியில்","f.lang.p":"டச்சு, வெல்ஷ், ஜப்பானியம் முதல் கடற்கொள்ளையர், யோடா, க்ளிங்கன் வரை 120-க்கும் மேற்பட்ட மொழிகள், கலைச்சொற்களுக்காக ஆங்கிலத்துக்கு விரைவாகத் திரும்பும் வசதியுடன்.","f.service.h":"ஒரு யோசனையிலிருந்து உண்மையான சேவை வரை","f.service.p":"மக்கள் இப்போது பயன்படுத்தும் ஒன்றை AI-உடன் உருவாக்கினீர்களா? அதைச் சேவை எனக் குறியிடுங்கள், அதை நன்றாக நடத்த போர்டு உதவும்: அப்டைம் சோதனைகள், பொது நிலைப் பக்கம், எழுதப்பட்ட ஆய்வுடன் சம்பவங்கள், Go தேவைப்படும் மாற்றங்கள், தினமும் சரிபார்க்கப்படும் பேக்கப்கள். நீங்கள் முன்னேறும்போதே உதவி ஒவ்வொரு படியையும் கற்றுத்தரும்.","msgr.h2":"AI-gile Messenger: உங்கள் குழு உங்கள் பாக்கெட்டில்","msgr.p1":"போர்டைத் திறக்காமலே உங்கள் AI குழுவிடம் பேசுங்கள். உங்கள் ப்ராஜெக்ட் லீட்களுடனும் நண்பர்களுடனும் அரட்டை அடியுங்கள், ஒரு கார்டின் சோதனைப் படிகளைப் பார்த்து பதில் சொல்லுங்கள், எல்லாம் உங்கள் போனிலிருந்தே.","msgr.p2":"இணைக்க, உங்கள் போர்டில் உள்ள QR குறியீட்டை ஸ்கேன் செய்யுங்கள். முதல் முறையா? ஒரு நட்பான டெமோ அரட்டை உங்களுக்கு எல்லாவற்றையும் காட்டும்.","msgr.when":"முதலில் Android, பிறகு போன்களுக்கும் iPhone-க்கும் ஒரு வலைப் பதிப்பு.","msgr.who":"உங்கள் ப்ராஜெக்ட் லீட்","msgr.b1":"டார்க் மோடு சரிசெய்தல் தயார். சோதனைப் படிகள் வேண்டுமா?","msgr.b2":"ஆமாம், தயவுசெய்து!","msgr.b3":"1. Settings-ஐத் திறக்கவும். 2. Dark-ஐத் தேர்ந்தெடுக்கவும். சரியாகத் தெரிகிறதா?","tl.aria":"முதல் உரையாடல் முதல் திட்டம் வரையிலான காலவரிசை","tl.h2":"முதல் அரட்டை முதல் அடுத்து வருவது வரை","tl.lede":"உண்மையான தேதிகளும் நேரங்களும், உங்கள் சொந்த நேர மண்டலத்தில். இன்றுக்குப் பிறகு அது திட்டம் மட்டுமே, தேதிகள் எதுவும் உறுதியளிக்கப்படவில்லை.","tl.today":"இன்று","tl.planned":"திட்டமிடப்பட்டது","tl.doing":"நடப்பில்","tl.cards.one":"{n} கார்டு","tl.cards.other":"{n} கார்டுகள்","join.h2":"இணையுங்கள்","join.lede":"AI-gile-ஐ AuDHD உள்ள, மனநலத்துடன் சில போராட்டங்களைச் சந்தித்த, தாடி வைத்த ஒரு விசித்திரமான மனிதரும் பொறுமையான ஏராளமான ஏஜென்ட்களும் உருவாக்குகிறார்கள். இப்போதைக்கு இது தனிப்பட்டது, நண்பர்களுடன் மூடிய ஆல்பாவில் உள்ளது. திறக்கும்போது முயற்சிக்க விரும்புகிறீர்களா?","join.btn":"ஆர்வத்தைப் பதிவு செய்","join.small":"மின்னஞ்சல் அனுப்புவோம், வேறு எதுவும் இல்லை","footer.tag":"AI-gile. டிராக்கர்கள் இல்லை, குக்கீகள் இல்லை, ஸ்டாண்ட்-அப் காபி இல்லை.","footer.licence":"வணிக உரிமம்","footer.status":"நிலை","footer.privacy":"நாங்கள் வைத்திருப்பவை","footer.thanks":"அழைப்புகளுக்கு ChilledChat-க்கு நன்றி","form.sending":"அனுப்புகிறது…","form.failed":"அது நடக்கவில்லை: பிறகு மீண்டும் முயற்சிக்கவும்.","form.offline":"AI-gile-ஐ அடைய முடியவில்லை: பிறகு மீண்டும் முயற்சிக்கவும்.","form.keep":"உங்களுக்குப் பதில் சொல்ல மட்டுமே இதைப் பயன்படுத்துவோம், பிறகு நீக்கிவிடுவோம். டிராக்கர்கள் இல்லை, குக்கீகள் இல்லை.","form.keepLink":"நாங்கள் வைத்திருப்பவை","interest.title":"AI-gile: ஆல்பா திறக்கும்போது சொல்லுங்கள்","interest.description":"AI-gile-இன் மூடிய ஆல்பா அல்லது பீட்டா திறக்கும்போது தெரிந்துகொள்ள உங்கள் மின்னஞ்சலை விடுங்கள்.","interest.h1":"🔔 திறக்கும்போது சொல்லுங்கள்","interest.lede":"AI-gile மூடிய ப்ரீ-ஆல்பாவில் உள்ளது. உங்கள் மின்னஞ்சலை விடுங்கள்; உங்களுக்கு இடம் இருக்கும்போது ஒரே ஒரு முறை எழுதுவோம்.","interest.email":"உங்கள் மின்னஞ்சல்","interest.which":"எந்தச் சோதனை?","interest.alpha":"மூடிய ஆல்பா: ஆரம்பம், கரடுமுரடு, நிறைய மாற்றங்கள்","interest.beta":"பீட்டா: நிலையானது, பிறகு","interest.both":"எதுவானாலும், எது முதலில் வருகிறதோ","interest.submit":"பட்டியலில் சேருங்கள்","interest.thanks":"நன்றி! நீங்கள் பட்டியலில் இருக்கிறீர்கள்.","licence.title":"AI-gile: வணிக உரிமம்","licence.description":"உங்கள் வணிகத்தில் AI-gile பயன்படுத்துகிறீர்களா? இலவச வணிக உரிமத்துக்கு விண்ணப்பியுங்கள்.","licence.h1":"📜 வணிக உரிமம்","licence.lede":"வேலையில் AI-gile பயன்படுத்துகிறீர்களா? நீங்கள் யார், என்ன செய்கிறீர்கள் என்று சொல்லுங்கள். அது ஏதாவது நன்மை செய்தால், உரிமம் இலவசம்.","licence.company":"நிறுவனம்","licence.website":"இணையதளம்","licence.what":"நீங்கள் என்ன செய்கிறீர்கள்","licence.how":"இது உலகுக்கு எப்படி உதவுகிறது","licence.email":"மின்னஞ்சல்","licence.submit":"விண்ணப்பி","licence.thanks":"நன்றி! மின்னஞ்சலில் பதிலளிப்போம்.","status.title":"AI-gile நிலை","status.h1":"AI-gile நிலை","status.quiet":"அமைதியாக இருக்கிறது","status.intro":"AI-gile இப்போது வேலை செய்கிறதா? இந்தப் பக்கம் 5 நிமிடங்களுக்கு ஒருமுறை இணையதளம், போர்டு பகிர்வு, அழைப்புகள், பதிவிறக்கம் ஆகியவற்றைச் சோதிக்கிறது.","status.up":"வேலை செய்கிறது ({ms} ms-இல் பதில்)","status.slow":"கடைசிச் சோதனைக்குப் பதில் இல்லை, மீண்டும் முயல்கிறது","status.down":"செயலிழந்துள்ளது: கடைசி இரண்டு சோதனைகளுக்கும் பதில் இல்லை","status.svc.web":"இணையதளம்","status.svc.web.offers":"இந்தத் தளம்: AI-gile என்றால் என்ன, மற்றும் ஆர்வப் படிவம்","status.svc.boards":"போர்டு பகிர்வு","status.svc.boards.offers":"பொது போர்டுகள், நண்பர்களுக்கிடையேயான செய்திகள், அழைப்பிதழ்கள்","status.svc.calls":"அழைப்புகள்","status.svc.calls.offers":"AI-gile-இல் குரல், வீடியோ, திரைப் பகிர்வு","status.svc.download":"பதிவிறக்கம்","status.svc.download.offers":"Windows நிறுவியும் அழைப்பிதழ் இணைப்புகளும்","status.checking":"சரிபார்க்கிறது…","status.offline":"நிலைச் சேவையை இப்போது அடைய முடியவில்லை (மீண்டும் முயல்கிறது)","status.updated":"{ago} புதுப்பிக்கப்பட்டது","status.justNow":"இப்போதுதான்","status.min":"{n} நிமிடம் முன்","status.hours":"{n} மணி முன்","status.days":"{n} நாள் முன்","privacy.title":"AI-gile: நாங்கள் வைத்திருப்பவை","privacy.h1":"நாங்கள் வைத்திருப்பவை","privacy.lede":"சுருக்கமாக: நீங்கள் அனுப்புவது மட்டும், அதுவும் நீண்ட காலத்துக்கு அல்ல.","privacy.only":"நீங்கள் அனுப்புவது மட்டும்: உங்கள் மின்னஞ்சல் போல, படிவத்தில் நீங்கள் தட்டச்சு செய்வது. உங்களைப் பற்றி வேறு எதுவும் இல்லை.","privacy.sealed":"எங்கள் சர்வர் படிக்க முடியாதபடி அது முத்திரையிடப்படுகிறது: அது புறப்படும் முன்பே உங்கள் உலாவியில் (பழைய உலாவியில், அது வந்து சேர்ந்த உடனே). எங்கள் சொந்த போர்டு மட்டுமே அதைத் திறக்க முடியும்.","privacy.server":"அது எங்கள் போர்டை அடைந்தவுடனே சர்வரிலிருந்து நீக்கப்படுகிறது. 30 நாட்களுக்குப் பிறகும் அங்கே மீதமிருப்பவை எப்படியும் நீக்கப்படும்.","privacy.board":"உங்களுக்குப் பதில் சொல்லும் வரை மட்டுமே அதை எங்கள் போர்டில் வைத்திருப்போம், பிறகு அங்கிருந்தும் நீக்கிவிடுவோம்.","privacy.none":"டிராக்கர்கள் இல்லை, குக்கீகள் இல்லை, பகுப்பாய்வு இல்லை.","privacy.local":"உங்கள் மொழியும் ஒளி அல்லது இருள் தேர்வும் உங்கள் உலாவியிலேயே இருக்கும். அவை ஒருபோதும் எங்களுக்கு அனுப்பப்படுவதில்லை.","privacy.ask":"இன்னும் சீக்கிரம் நீக்க வேண்டுமா? எங்கள் மின்னஞ்சலுக்குப் பதிலளித்துச் சொல்லுங்கள்.","live.h2":"இது உருவாவதை நேரலையில் பாருங்கள்","live.caption":"ஒவ்வொரு அட்டையும் மறைக்கப்பட்டுள்ளது: நீங்கள் வேலையின் வடிவத்தைப் பார்க்கிறீர்கள், சொற்களை அல்ல.","live.watching.one":"நேரலை: {n} பேர் பார்க்கிறார்கள்","live.watching.other":"நேரலை: {n} பேர் பார்க்கிறார்கள்","live.last.now":"கடைசி அட்டை இப்போதுதான் நகர்த்தப்பட்டது","live.last.min.one":"கடைசி அட்டை {n} நிமிடம் முன்பு நகர்த்தப்பட்டது","live.last.min.other":"கடைசி அட்டை {n} நிமிடங்கள் முன்பு நகர்த்தப்பட்டது","live.last.hour.one":"கடைசி அட்டை {n} மணி நேரம் முன்பு நகர்த்தப்பட்டது","live.last.hour.other":"கடைசி அட்டை {n} மணி நேரம் முன்பு நகர்த்தப்பட்டது","live.last.day.one":"கடைசி அட்டை {n} நாள் முன்பு நகர்த்தப்பட்டது","live.last.day.other":"கடைசி அட்டை {n} நாட்கள் முன்பு நகர்த்தப்பட்டது","live.offline":"நேரலைப் பலகை சற்று ஓய்வெடுக்கிறது. விரைவில் மீண்டும் பாருங்கள்.","live.cols":"பேக்லாக்|செய்ய வேண்டியவை|நடப்பில்|டீம் சரிபார்க்கிறது|நீங்கள் டெஸ்ட் செய்ய|டீமுக்கு|முடிந்தது","footer.models":"AI-gile உங்களுக்காக AI மாடல்களை இயக்குகிறது. அவை சொல்வதும் செய்வதும் அவற்றினுடையது, எனவே நம்புவதற்கு முன் சரிபாருங்கள்.","privacy.ai.h":"AI பகுதி","privacy.ai.models":"AI-gile என்பது போர்டு. வேலையை மற்ற நிறுவனங்களின் AI மாடல்கள் செய்கின்றன, Claude, Codex, Gemini போன்றவை, உங்கள் சொந்த கணக்குகளில்.","privacy.ai.check":"அவை எழுதுவதும் செய்வதும் அவற்றிடமிருந்தே வருகிறது, தவறாகவும் இருக்கலாம். சார்ந்திருக்கும் முன் அல்லது வெளியிடும் முன் சரிபாருங்கள்.","privacy.ai.files":"நீங்கள் இணைக்கும் கோப்புறைகளில் அவை கோப்புகளை மாற்றி கட்டளைகளை இயக்கும். காப்புப் பிரதி வைத்திருங்கள்.","privacy.ai.send":"நீங்கள் ஒரு மாடலுக்குக் கொடுப்பது அதை இயக்கும் நிறுவனத்திடம், அவர்களின் விதிமுறைகளின்படி செல்கிறது. ஒவ்வொன்றின் விதிமுறைகளும் கட்டணங்களும் பொருந்தும்.","privacy.ai.asis":"AI-gile ஆரம்பகால சோதனைப் பதிப்பு, இருப்பது இருப்பதுபோல் வழங்கப்படுகிறது."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["கான்பன்.","ரோபோக்கள்.","ஒப்படைத்தல்."]},{"n":2,"texts":["ரோபோ கான்பன்.","ஏஜென்ட்கள், ஒழுங்காக.","யோசனைகள், உருவாகின்றன."]},{"n":3,"texts":["ரோபோக்களுக்கான கான்பன்.","யோசனை அம்சமாகிறது.","இலவச ஏஜென்ட் கான்பன்."]},{"n":5,"texts":["ஏஜென்ட்கள் நடத்தும் கான்பன் போர்டு.","நீங்கள் எழுதுங்கள். ஏஜென்ட்கள் உருவாக்குவார்கள்.","இலவசம், உள்ளூர், சோதிக்கப்பட்டது, கொஞ்சம் குறும்பு."]},{"n":8,"texts":["AI ஏஜென்ட்கள் வேலை செய்யும் இலவச கான்பன் போர்டு.","யோசனையை எழுதுங்கள். ஏஜென்ட்கள் உருவாக்கும். நீங்கள் ஏற்கலாம்.","ஒரு மனிதருக்கும் பல பொறுமையான ரோபோக்களுக்குமான அஜைல்."]},{"n":13,"texts":["AI ஏஜென்ட்கள் கார்டுகளை எடுத்து உருவாக்கும், உங்கள் கணினியில் இயங்கும் ஒரு கான்பன் போர்டு.","உங்கள் யோசனையை எழுதுங்கள். அதை ஏஜென்ட்களின் ஒரு டீம் உருவாக்கும். ஒரு டெஸ்டர் அதைச் சரிபார்த்த பிறகு, நீங்களே முடிவு செய்வீர்கள்.","இலவசம், கணக்கு இல்லை, டிராக்கர் இல்லை: ஒரு போர்டு, சில ரோபோக்கள், நீங்களே தலைவர்."]},{"n":21,"texts":["AI-gile என்பது AI கோடிங் ஏஜென்ட்களுடன் சேர்ந்து வேலை செய்ய உதவும் ஒரு கான்பன் போர்டு. கார்டுகளை அவை எடுத்துச் செய்யும்; அவற்றைச் சோதித்து ஏற்பது நீங்கள்.","ஒவ்வொரு ப்ராஜெக்டுக்கும் ஒரு லீடும், AI ஏஜென்ட்கள் அடங்கிய ஒரு டீமும் கிடைக்கும். எந்த ஒரு கார்டிலும் கருத்து எழுதினால், உடனே டீம் வேலையைத் தொடங்கும்.","உங்கள் சொந்த கணினியில் ஓடும், இலவசமான ஒரு தனிப்பட்ட செய்ய வேண்டியவை பட்டியல் இது. வேலை செய்பவர்கள் எல்லாம் ரோபோக்கள். சரி என்று சொல்பவர் மட்டும் நீங்கள்."]},{"n":34,"texts":["உங்கள் யோசனைகளை ஒரு போர்டில் வைக்கிறீர்கள். AI ஏஜென்ட்களின் ஒரு டீம் அவற்றை வேலை செய்யும் அம்சங்களாக மாற்றி, சோதித்து, நீங்கள் முயன்று பார்க்கத் தேவையான படிகளுடன் திருப்பித் தருகிறது. நீங்கள் சொல்லும் வரை எதுவும் முடிந்ததாகக் கணக்கில் வராது.","AI-gile என்பது வீட்டிலேயே செய்த ஒரு கான்பன் போர்டு. இதை ரிச், தான் இப்போது நிர்வகிக்கும் அதே ஏஜென்ட்களின் பெரிய உதவியுடன் உருவாக்கினார். இது இலவசம், உங்கள் கணினியில் ஓடும், நண்பர்களுடன் பகிரப்படுகிறது, விற்கப்படுவதில்லை. இது நண்பர்களுக்காகச் செய்த ஒரு சிறிய முயற்சி.","பேக்லாக் முதல் முடிந்தது வரை நெடுவரிசைகள் கொண்ட சாதாரண கான்பன் போர்டை நினைத்துப் பாருங்கள், கார்டுகளை AI ஏஜென்ட்கள் எடுக்கின்றன என்பது மட்டும் வேறுபாடு. அவை முன்னேற்றம் சொல்லும், சிக்கினால் கேட்கும், உங்கள் பெருவிரல் உயர்வுக்காக எப்போதும் காத்திருக்கும்."]},{"n":55,"texts":["AI-gile என்பது ஒரு கான்பன் போர்டு, இதில் டீமே AI ஏஜென்ட்களால் ஆனது. ஒவ்வொரு ப்ராஜெக்டிலும் வேலையைத் திட்டமிடும் ஒரு லீடும், அதை உருவாக்கும் உதவியாளர்களும் இருக்கிறார்கள். ஒரு அம்சம் தயாரானதும் AI டெஸ்டர் அதைச் சோதித்து ஒரு ஸ்கிரீன்ஷாட் எடுப்பார், பிறகு அது உங்கள் குவியலுக்கு வந்து சேரும். அதை ஏற்கலாம், அல்லது கருத்து எழுதினால் அவர்கள் மீண்டும் செய்வார்கள்.","இது ஒருவர் பல AI கோடிங் அமர்வுகளை ஒரே நேரத்தில் கண்காணிக்க ஆரம்பித்த ஒரு வழி, பிறகு வளர்ந்து ஒரு முழுமையான போர்டு ஆனது. இது உங்கள் கணினியிலேயே ஓடும், கணக்கு எதுவும் தேவையில்லை, டிராக்கர்களும் இல்லை. நண்பர்களுக்கும் ஆர்வமுள்ள எவருக்கும் இலவசம். இது இன்னும் முடியவில்லை, அதனால் சில கரடுமுரடான இடங்களையும் எப்போதாவது ஒரு ஆச்சரியத்தையும் எதிர்பாருங்கள். அதைப் புரிந்துகொண்டு பொறுத்துக்கொள்ளுங்கள், நன்றி.","நேர்மையான பதிப்பு இதோ. யோசனைகள் வைத்திருப்பதும் முடிவுகளைச் சரிபார்ப்பதும் இன்னும் உங்கள் வேலைதான். அதற்கு நடுவில் உள்ள எல்லாவற்றையும் AI-gile செய்கிறது: கார்டுகளை ஒழுங்காக வைக்கிறது, நீங்கள் கருத்து எழுதினால் சரியான ஏஜென்ட்டை எழுப்புகிறது, என்ன மாறியது என்று சரியாகக் காட்டுகிறது, இவை எல்லாவற்றையும் உங்களுக்காக ஒரே ஒரு சிறிய குவியலில் வைக்கிறது. அதனால் ஒரு ஆப்பிலிருந்து இன்னொன்றுக்கு அலைய வேண்டியதில்லை, எதையும் தவற விடவும் மாட்டீர்கள்."]},{"n":89,"texts":["AI-gile என்பது நீங்கள் உங்கள் சொந்த கணினியில் ஓட்டும் ஒரு இலவச கான்பன் போர்டு. மனிதர்களுக்குப் பதிலாக, ஒவ்வொரு ப்ராஜெக்டிலும் AI ஏஜென்ட்களின் ஒரு டீம் இருக்கிறது: உங்கள் யோசனைகளை கார்டுகளாகவும் ஒரு திட்டமாகவும் மாற்றும் ஒரு லீடு, முன்னுரிமை வரிசையில் கார்டுகளை எடுத்துச் செய்யும் உதவியாளர்கள். ஏதாவது உருவானதும், ஒரு AI டெஸ்டர் சோதனைப் படிகளைப் பின்பற்றி, தான் பார்த்ததை உங்களுக்குக் காட்டுவார். பிறகு அது \"உங்களுக்கு\" என்ற ஒரே குவியலில் காத்திருக்கும். நீங்கள் ஏற்கலாம், அல்லது கருத்து எழுதினால் டீம் மீண்டும் ஒரு முறை முயலும். நீங்கள் இல்லாமல் எதுவும் ஒருபோதும் முடிந்தது நெடுவரிசையை அடையாது. இதுவே இதன் முக்கிய விதி.","நீங்கள் எதிர்பார்க்காத சில விஷயங்கள் உண்டு. நீங்கள் தூங்கும்போது இரவுக் காவல், உங்கள் பதில் தேவைப்படாத கார்டுகளைத் தேர்ந்தெடுத்து, செய்ய வேண்டியவை நெடுவரிசையை நிரப்பி வைக்கும். ஏஜென்ட்கள் இன்றும் இந்த வாரமும் எவ்வளவு பயன்படுத்தின என்பதை ஒரு டோக்கன் எண்ணி காட்டும், No Token Mode அவற்றைச் செலவழிப்பதை நிறுத்தச் சொல்லும். நண்பர்களுக்குச் செய்தி அனுப்பலாம், தனிப்பட்ட செய்திகள் தொடக்கம் முதல் இறுதி வரை குறியாக்கம் செய்யப்படுகின்றன. போர்டு டச்சு, ஃபிளெமிஷ், கடற்கொள்ளையர், க்ளிங்கன் உட்பட சுமார் 120 மொழிகளில் பேசும். இவை எதற்கும் ஒரு பைசா கூடச் செலவில்லை, உங்களிடம் எதையும் விற்க யாரும் முயலவும் இல்லை. இவை எல்லாம் நண்பர்களுக்காக, அன்புடன் செய்யப்பட்டவை.","AI-gile ஒரு சிறிய, தனிப்பட்ட திட்டம், ஒரு நிறுவனம் அல்ல. பல AI கோடிங் ப்ராஜெக்ட்களை, ஒவ்வொரு ஆப்பையும் திறந்து பார்க்காமலே கவனிக்க ரிச் விரும்பினார். அதனால் அவரும் ஏஜென்ட்களும் அதற்காக ஒரு போர்டை உருவாக்கி, பிறகு அந்தப் போர்டையே பயன்படுத்தி அதன் மீதிப் பகுதியையும் உருவாக்கினார்கள். இது மூடிய ப்ரீ-ஆல்பாவில் இருக்கிறது, அதாவது ஒரு சில நண்பர்களுக்கு, பெரும்பாலும் வேலை செய்கிறது. விலைப் பக்கம் இல்லை, செய்திமடல் இல்லை, வளர்ச்சித் திட்டமும் இல்லை. பயனுள்ளதாகத் தோன்றினால், இது இன்னும் கொஞ்சம் திறந்ததும் முயன்று பார்க்கக் கேட்கலாம். அதுவரை பொறுமையாகக் காத்திருந்து, எங்களுடன் சேர்ந்து இதைச் சோதிக்க வாருங்கள், உங்கள் கருத்துகள் எங்களுக்கு மிகவும் உதவும்."]},{"n":144,"texts":["AI-gile என்பது ஒரு மனிதருக்கும் பல AI ஏஜென்ட்களுக்குமான ஒரு கான்பன் போர்டு. இது உங்கள் சொந்த கணினியில் ஓடும், முற்றிலும் இலவசம். நீங்கள் ப்ராஜெக்ட்களைச் சேர்க்கிறீர்கள், ஒவ்வொரு ப்ராஜெக்டுக்கும் ஒரு லீடும் ஒரு சிறிய டீமும் கிடைக்கும். Discord போல லீடுடன் அரட்டையடித்து ஒரு யோசனையை விவரிக்கிறீர்கள்; லீடு அதை கார்டுகளாகவும் ஒரு திட்டமாகவும் மாற்றி, நீங்கள் \"தொடங்கு\" என்று அழுத்தும் வரை காத்திருக்கும். மொழி மாதிரிகளுக்காகவே செய்யப்பட்ட ஒரு எளிய கட்டளை வரிக் கருவியைப் பயன்படுத்தி, டீம் கார்டுகளை முன்னுரிமை வரிசையில் ஒன்றன் பின் ஒன்றாகச் செய்யும். எதுவும் உங்களிடம் திரும்பி வருவதற்கு முன், ஒரு AI டெஸ்டர் ஆப்பின் ஒரு நகலில் படிகளைப் பின்பற்றி, ஒரு ஸ்கிரீன்ஷாட்டையும் இணைக்கும். முடிந்த வேலை, மாறிய கோப்புகளுடனும் வேறுபாட்டுடனும் உங்கள் குவியலில் வந்து சேரும். நீங்கள் அதை ஏற்கலாம், அல்லது ஒரு கருத்து எழுதினால் டீம் எழுந்து மீண்டும் முயலும். ஒரு கார்டை \"முடிந்தது\" நெடுவரிசைக்கு நகர்த்த உங்களால் மட்டுமே முடியும். அதனால் எந்த நேரத்திலும், எந்தக் கார்டு எங்கே இருக்கிறது என்பதை நீங்கள் ஒரே பார்வையில் தெரிந்துகொள்ளலாம், எதையும் தேட வேண்டியதில்லை.","AI-gile-உடன் ஒரு நாள், தோராயமாக இப்படி இருக்கும். மாலையில் நீங்கள் சில கருத்துகளை எழுதி வைக்கிறீர்கள்: இந்தப் பொத்தான் தவறான இடத்தில் இருக்கிறது, அந்தப் பட்டியலை வரிசைப்படுத்த வேண்டும், இருண்ட பயன்முறை கிடைக்குமா. பிறகு தூங்கப் போகிறீர்கள். ஏஜென்ட்கள் அந்தக் கருத்துகளைப் படித்து, மாற்றங்களைச் செய்து, அவற்றைச் சோதித்து, உங்களிடம் திருப்பித் தருகின்றன. செய்ய வேண்டியவை காலியாகிவிட்டால், இரவுக் காவல் உங்கள் பதில் தேவைப்படாத கார்டுகளைக் கொண்டு பேக்லாக்கிலிருந்து அதை நிரப்பும். காலையில் ஒரே ஒரு சிறிய குவியல் காத்திருக்கும்: ஓரிரு கேள்விகள், சோதிக்க சில விஷயங்கள், ஒவ்வொன்றும் தூக்கக் கலக்கத்தில் இருப்பவரும் பின்பற்றக்கூடிய படிகளுடனும், அது வேலை செய்வதைக் காட்டும் ஒரு ஸ்கிரீன்ஷாட்டுடனும். நீங்கள் கிளிக் செய்து, நல்லவற்றை ஏற்று, மீதியைத் திருப்பி அனுப்புகிறீர்கள். இவை எல்லாம் எவ்வளவு பயன்படுத்தின என்பதை டோக்கன் எண்ணி காட்டும், சிக்கனமான வாரங்களுக்கு No Token Mode இருக்கிறது. பிறகு நீங்கள் காலை உணவு சாப்பிடுகிறீர்கள், அதில் மட்டும் ஏஜென்ட்களால் இன்னும் உதவ முடியாது. அடுத்த நாள் இரவும் இதே போல் தொடரும், அப்போது உங்களுக்கு வேண்டியது ஒரு கப் தேநீர் மட்டும்தான்.","முதலில், AI-gile என்னவாக இல்லை என்று பார்ப்போம். இது ஒரு ஸ்டார்ட்-அப் அல்ல, விற்பனைக்கு இல்லை, உங்கள் தரவை யாரும் சேகரிக்கவும் இல்லை. இது உங்கள் கணினியில் ஓடும் இலவசப் போர்டு, கணக்குகள் இல்லை, டிராக்கர்கள் இல்லை, குக்கீகளும் இல்லை. இது என்னவாக இருக்கிறது என்றால்: உங்கள் எல்லா AI கோடிங் ப்ராஜெக்ட்களையும் ஒரே நேரத்தில் பார்க்க ஒரு ஒழுங்கான இடம், கார்டுகளை ஏஜென்ட்களின் டீம் செய்ய, முடிவுகளை நீங்கள் எடுக்க. தொடர்புடைய கார்டுகளை ஒன்றாக இணைக்கிறது, குழப்பமான தலைப்புகளைச் சரிசெய்கிறது, கோடு எவ்வளவு எளிமையாக இருக்கிறது என்றும் கவனிக்கிறது. டச்சு, ஃபிளெமிஷ் முதல் கடற்கொள்ளையர், க்ளிங்கன் வரை சுமார் 120 மொழிகளில் பேசுகிறது. நண்பர்கள் ஒருவருக்கொருவர் தனிப்பட்ட முறையில், குறியாக்கத்துடன் செய்தி அனுப்பிக்கொள்ளலாம். இதை ரிச்சும் பொறுமையான ஏராளமான ஏஜென்ட்களும் சேர்ந்து உருவாக்கினார்கள், பெரும்பாலும் இதையே பயன்படுத்தி. இது மூடிய ப்ரீ-ஆல்பாவில் இருக்கிறது, அதனால் சில இடங்களில் கரடுமுரடாக இருக்கும். வேடிக்கையாகத் தோன்றினால், அன்பாகக் கேளுங்கள், சீக்கிரமே உள்ளே வரலாம். எனவே உங்களுக்கு விருப்பமிருந்தால், எந்தத் தயக்கமும் இல்லாமல் எங்களிடம் வந்து கேளுங்கள், நாங்கள் மகிழ்வோம்."]}],"quips":{"1":"ஒரே சொல். துணிச்சல். ஒருவேளை அதிகத் துணிச்சல்.","3":"மூன்று சொற்கள். பெரும்பாலான தயாரிப்புப் பக்கங்களை விட ஏற்கனவே நேர்மையானது.","8":"எட்டுச் சொற்கள். இன்னும் ஸ்டாண்ட்-அப்பை விடச் சிறியது.","21":"நீளங்கள் ஸ்டோரி பாயிண்ட்கள், சொல்லப்போனால். நிச்சயமாக அப்படித்தான்.","55":"ஐம்பத்தைந்து சொற்கள். இதைப் படிக்கும்போது இரண்டு கார்டுகள் முடிந்துவிட்டன.","144":"இதுதான் நீளமானது. 233 என்பது இல்லை. ஏஜென்ட்கள் தூங்கப் போய்விட்டன."}},"timeline":{"first-idea.name":"முதல் யோசனை","first-idea.line":"ஒரு வரி கோடும் இல்லாத காலத்தில் நடந்த முதல் உரையாடல்.","first-board.name":"முதல் போர்டு","first-board.line":"தன் சொந்த உருவாக்கத்தைத் தானே கண்காணிக்கும் போர்டு: கார்டுகள், நெடுவரிசைகள், இழுத்துவிடுதல், ப்ராஜெக்ட்கள்.","team-roles.name":"டீமும் பங்குகளும்","team-roles.line":"ஏஜென்ட் சுயவிவரங்கள், டீம் வார்ப்புருக்கள், இடங்கள், யார் என்ன செய்கிறார்கள்.","install.name":"நிறுவலும் வெளியீடுகளும்","install.line":"நண்பர் நிறுவக்கூடிய ஒரு zip, தானியங்கிப் புதுப்பிப்பு, சேனல்கள், பின்னோக்கித் திரும்புதல்.","usage-saver.name":"பயன்பாட்டுச் சேமிப்பு","usage-saver.line":"இயக்கங்களுக்கான செலவை அளவிடுங்கள், கோடை எளிமையாக வையுங்கள், உங்கள் வரம்பைச் சேமியுங்கள்.","friends.name":"நண்பர்களும் பகிர்வும்","friends.line":"தனிப்பட்ட செய்திகள், குறியாக்கப்பட்ட ரிலே, அழைப்புகள், பங்குகள், பகிரப்பட்ட ப்ராஜெக்ட்கள்.","languages.name":"மொழிகள்","languages.line":"ஒவ்வொரு திரை உரையும் ஒரு மொழிக் கோப்பில், முதலில் டச்சு மற்றும் ஃபிளெமிஷ்.","ai-tester.name":"AI டெஸ்டர்","ai-tester.line":"ஒவ்வொரு ஒப்படைப்பையும் டெஸ்டர் முதலில் சரிபார்த்து, தான் பார்த்ததைக் காட்டுகிறார்.","website.name":"இணையதளம்","website.line":"aigile.lol, முன்னோட்டப் பக்கம் மற்றும் இந்தக் காலவரிசை.","streaming.name":"அரட்டையும் ஸ்ட்ரீமிங்கும்","streaming.line":"Discord, Twitch, OBS, ஸ்ட்ரீமர் பயன்முறை, GIF-களும் எமோஜிகளும்.","no-ai.name":"AI இல்லாத பதிப்பு","no-ai.line":"AI இல்லாமல் கோடிங் செய்பவர்களுக்கான போர்டு, மற்றும் பொது போர்டுகள்.","night-watch.name":"இரவுக் காவல்","night-watch.line":"நீங்கள் தூங்கும்போது காவலரும் Scrum Master-உம் டீம்களை வேலையில் வைத்திருக்கிறார்கள்.","p-more.name":"மற்ற எல்லாம்","p-more.line":"தங்கள் முறைக்காகக் காத்திருக்கும் சிறிய யோசனைகள்.","p-android.name":"போனும் Android-உம்","p-android.line":"போனிலிருந்து உங்கள் போர்டை அணுகுங்கள், பிறகு சொந்த Android ஆப்.","p-release.name":"ஆல்பாவும் அதற்குப் பிறகும்","p-release.line":"மூடிய ஆல்பா, நேரடித் தளம், பிறகு பீட்டா.","p-languages.name":"மேலும் மொழிகள்","p-languages.line":"130 மொழிகள், மொழி கற்பவர்களுக்கு ஒரு மூழ்கல் பயன்முறையும்.","p-engines.name":"மேலும் AI என்ஜின்கள்","p-engines.line":"ஒவ்வொரு ஏஜென்டுக்கும் Claude, Codex, Gemini, Copilot அல்லது Cursor ஐத் தேர்ந்தெடுங்கள்.","p-pro.name":"தொழில்முறை நடைமுறை","p-pro.line":"ஆபத்து லேபிள்கள், மெர்ஜ் வாயில்கள், சம்பவ கார்டுகள், பாதுகாப்புத் தடுப்புகள்.","p-self.name":"உங்களைக் கவனித்துக்கொள்ள","p-self.line":"சோர்வுப் பயன்முறை, சுய-கவனிப்பு நினைவூட்டல்கள், 4:20.","p-servers.name":"சர்வர்களும் வளர்ச்சியும்","p-servers.line":"உலகளாவிய சர்வர் அமைப்புகள், பங்குகள், வளர்ச்சிக்கான திட்டமிடல்.","p-livestream.name":"ஸ்ட்ரீமிங் கூடுதல்கள்","p-livestream.line":"Twitch அரட்டை, தனிப்பயன் எமோஜிகள், பொது நேரலைக் காட்சி."},"words":{"button":"📖 கலைச்சொற்கள்","h":"📖 சொற்கள் விளக்கம்","intro":"எளிய மொழியில் இலவசப் பயிற்சி: முதல் எண்ணம் முதல் மக்கள் சார்ந்திருக்கும் சேவை வரை நீங்கள் சந்திக்கும் ஒவ்வொரு சொல்லும், வழியில் அஜைல், கட்டுதல், பாதுகாப்பாக வைத்திருத்தல், AI-யுடன் வேலை செய்தல் ஆகியவற்றுடன்.","search":"ஒரு சொல்லைத் தேடு…","none":"அந்தச் சொல் எதுவும் பொருந்தவில்லை.","close":"மூடு","count":{"one":"{count} சொல்","other":"{count} சொற்கள்"},"groups":[{"id":"idea","name":"💡 ஐடியாவும் கண்டறிதலும்"},{"id":"plan","name":"🗺️ வேலையைத் திட்டமிடுதல்"},{"id":"agile","name":"🔁 அஜைல் வேலை முறைகள்"},{"id":"build","name":"🛠️ உருவாக்குதல்"},{"id":"test","name":"🧪 சோதனையும் தரமும்"},{"id":"change","name":"🔀 பாதுகாப்பாக மாற்றுதல்"},{"id":"run","name":"🛎️ ஒரு சேவையை நடத்துதல்"},{"id":"sec","name":"🔒 பாதுகாப்பும் தனியுரிமையும்"},{"id":"ai","name":"🤖 AI-யுடன் வேலை செய்தல்"},{"id":"money","name":"💰 பணமும் உரிமங்களும்"}],"list":[{"id":"discovery","g":"idea","word":"கண்டறிதல் (டிஸ்கவரி)","text":"எதையும் உருவாக்கும் முன், எந்தப் பிரச்சினையைத் தீர்ப்பது மதிப்புள்ளது, யாருக்காக என்று கண்டுபிடிக்கும் ஆரம்பக் கட்டம்.","also":["கண்டறிதல் கட்டம்","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"பிரச்சினை அறிக்கை","text":"யாருக்கு என்ன பிரச்சினை, அது ஏன் முக்கியம் என்பதைச் சொல்லும் ஒன்றிரண்டு வாக்கியங்கள்; எல்லோரும் ஒரே இலக்கை நோக்கிச் செல்ல இது உதவும்.","also":["பிரச்சினை அறிக்கைகள்","problem statement","problem statements"]},{"id":"user","g":"idea","word":"பயனர்","text":"நீங்கள் உருவாக்குவதைப் பயன்படுத்தும் நபர். வேலை அவர்களின் தேவைகளுக்காகவே.","also":["பயனர்கள்","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"பங்குதாரர் (ஸ்டேக்ஹோல்டர்)","text":"வேலையின் முடிவில் அக்கறை உள்ள அல்லது அதனால் பாதிக்கப்படும் எவரும்; அதற்குப் பணம் கொடுப்பவர்கள், பயன்படுத்துபவர்கள், ஆதரவளிப்பவர்கள் போல.","also":["பங்குதாரர்கள்","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"பெர்சோனா","text":"ஒரு வகைப் பயனரைப் பிரதிநிதித்துவப்படுத்தும் கற்பனையான ஆனால் நம்பத்தகுந்த நபர்; அதனால் டீம் “இது சாமுக்கு எளிதாக இருக்குமா?” என்று கேட்க முடியும்.","also":["பெர்சோனாக்கள்","persona","personas"]},{"id":"userresearch","g":"idea","word":"பயனர் ஆய்வு","text":"ஊகிக்காமல், உண்மையான மனிதர்களிடம் பேசியும் அவர்களைக் கவனித்தும் அவர்களுக்கு என்ன தேவை என்று அறிதல்.","also":["பயனர் நேர்காணல்கள்","user research","user interviews"]},{"id":"journey","g":"idea","word":"பயனர் பயணம்","text":"ஒருவர் ஒரு காரியத்தை முடிக்க எடுக்கும் படிகள், அதைப் பற்றி முதலில் கேள்விப்பட்டதிலிருந்து முடிக்கும் வரை; உங்கள் தயாரிப்புக்கு வெளியே நடப்பவையும் சேர்த்து. இதை வரைந்து பார்த்தால் அவர்கள் எங்கே சிக்குகிறார்கள் என்று தெரியும்.","also":["பயனர் பயணங்கள்","வாடிக்கையாளர் பயணம்","user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"சிரமப் புள்ளி (பெயின் பாயிண்ட்)","text":"இன்று மக்களை எரிச்சலூட்டும் அல்லது தாமதப்படுத்தும் ஒன்று. நல்ல தயாரிப்புகள் இந்தச் சிரமங்களை நீக்கும்.","also":["சிரமப் புள்ளிகள்","pain point","pain points"]},{"id":"assumption","g":"idea","word":"அனுமானம்","text":"நீங்கள் நம்புகிறீர்கள் ஆனால் இன்னும் சரிபார்க்காத ஒன்று. அனுமானங்களை எழுதி வைத்தால் முதலில் எதைச் சோதிக்க வேண்டும் என்று தெரியும்.","also":["அனுமானங்கள்","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"கருதுகோள் (ஹைப்போதீசிஸ்)","text":"நீங்கள் சரிபார்க்கத் திட்டமிடும் சிறந்த ஊகம், என்ன நடக்கும் என்ற எதிர்பார்ப்புடன்; உதாரணமாக “முதல் மாதம் இலவசம் என்றால் மக்கள் பதிவு செய்வார்கள்”.","also":["கருதுகோள்கள்","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"பரிசோதனை","text":"ஓர் எண்ணம் வேலை செய்யுமா என்று அறிய, அதில் அதிகமாக முதலீடு செய்வதற்கு முன் நடத்தும் சிறிய திட்டமிட்ட சோதனை.","also":["பரிசோதனைகள்","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"கருத்துச் சான்று (PoC)","text":"ஓர் எண்ணம் வேலை செய்யுமா என்று பார்க்கச் செய்யும் விரைவான, கச்சா முயற்சி. பதில் கிடைத்ததும் பொதுவாக அதைத் தூக்கி எறிந்துவிடுவார்கள்.","also":["PoC","proof of concept","கருத்து நிரூபணம்"]},{"id":"prototype","g":"idea","word":"முன்மாதிரி (ப்ரோட்டோடைப்)","text":"தயாரிப்பின் ஆரம்ப மாதிரி, பெரும்பாலும் கிளிக் செய்யக்கூடிய படங்கள்; முறையாகக் கட்டுவதற்கு முன் எண்ணத்தை மக்களிடம் சோதித்துப் பார்க்க.","also":["முன்மாதிரிகள்","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"வயர்ஃப்ரேம்","text":"நிறங்களோ உண்மையான உள்ளடக்கமோ இல்லாமல், எது எங்கே இருக்கும் என்பதைக் காட்டும் திரையின் எளிய வரைபடம்.","also":["வயர்ஃப்ரேம்கள்","wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"மாக்கப் (தோற்ற மாதிரி)","text":"ஒரு திரை எப்படித் தெரியும் என்பதன் விரிவான படம், உண்மையான நிறங்களும் எழுத்துகளும் இருக்கும்; ஆனால் இன்னும் எதுவும் வேலை செய்யாது.","also":["மாக்கப்கள்","mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"வணிக நியாயம் (பிசினஸ் கேஸ்)","text":"ஒரு ப்ராஜெக்ட்டைச் செய்வதற்கான காரணங்கள்: அதற்கு எவ்வளவு செலவு, என்ன வருமானம் அல்லது சேமிப்பு, என்ன அபாயங்கள்.","also":["வணிக நியாயங்கள்","business case","business cases"]},{"id":"feasibility","g":"idea","word":"சாத்தியக்கூறு","text":"உங்களிடம் உள்ள நேரம், பணம், திறமைகளுடன் ஒன்றை உண்மையிலேயே கட்டவும் பராமரிக்கவும் முடியுமா என்பது.","also":["feasibility"]},{"id":"outcome","g":"idea","word":"விளைவு (அவுட்கம்)","text":"மக்களுக்கு நீங்கள் விரும்பும் மாற்றம், உதாரணமாக தவறவிடப்படும் சந்திப்புகள் குறைவது. எவ்வளவு கட்டுகிறீர்கள் என்பதை விட இதுவே முக்கியம்.","also":["விளைவுகள்","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"அவுட்புட் (உருவாக்கியவை)","text":"ஒரு புதிய திரை அல்லது அறிக்கை போல டீம் உருவாக்கும் ஒன்று. அதை உருவாக்கினால் தானாகவே யாருக்காவது உதவும் என்று அர்த்தமில்லை.","also":["அவுட்புட்கள்","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"வெற்றி அளவீடு","text":"வேலை அதன் நோக்கத்தை நிறைவேற்றியதா என்று சொல்லும் ஓர் எண்; உதாரணமாக தங்கள் ஆர்டரை முடிக்கும் மக்களின் எண்ணிக்கை கூடுவது.","also":["வெற்றி அளவீடுகள்","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"முக்கிய செயல்திறன் குறிகாட்டி (KPI)","text":"காரியங்கள் நன்றாகப் போகின்றனவா என்று பார்க்க நீங்கள் கவனிக்கும் முக்கிய எண்; உதாரணமாக வாரத்துக்குப் பதிவு செய்பவர்கள்.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"குறிக்கோள்களும் முக்கிய முடிவுகளும் (OKR)","text":"இலக்கு நிர்ணயிக்கும் ஒரு முறை: குறிக்கோள் நீங்கள் என்ன விரும்புகிறீர்கள் என்று சொல்லும்; சில முக்கிய முடிவுகள் அங்கே சேர்ந்துவிட்டீர்கள் என்று காட்டும் எண்கள்.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"தயாரிப்பு (ப்ராடக்ட்)","text":"ஆப், இணையதளம் அல்லது கருவி போல, பயனர்களுக்காகக் கட்டப்பட்டுப் பராமரிக்கப்படும் ஒன்று.","also":["தயாரிப்புகள்","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"தயாரிப்புத் தொலைநோக்கு (ப்ராடக்ட் விஷன்)","text":"இந்தத் தயாரிப்பு யாருக்கு உதவுகிறது, நீண்ட காலத்தில் எங்கே செல்கிறது என்பதைச் சொல்லும் சிறு அறிக்கை.","also":["தொலைநோக்கு","vision statement","product vision"]},{"id":"po","g":"plan","word":"ப்ராடக்ட் ஓனர் (PO)","text":"எதைக் கட்ட வேண்டும், எந்த வரிசையில் என்று முடிவு செய்பவர்; அதனால் டீம் எப்போதும் மிக முக்கியமானதில் வேலை செய்யும். AI-gile-இல் அது நீங்கள்தான்.","also":["PO","product owner","product owners","தயாரிப்பு உரிமையாளர்"]},{"id":"pm","g":"plan","word":"ப்ராடக்ட் மேனேஜர் (PM)","text":"ஒரு தயாரிப்பின் திசையைக் கவனிப்பவர்: அது எந்தப் பிரச்சினைகளை, யாருக்காக, ஏன் தீர்க்கிறது. PM என்பது ப்ராஜெக்ட் மேனேஜரையும் குறிக்கலாம், எனவே எது என்று பாருங்கள்.","also":["PM","product manager","product managers","தயாரிப்பு மேலாளர்"]},{"id":"projmgr","g":"plan","word":"திட்ட மேலாளர் (ப்ராஜெக்ட் மேனேஜர்)","text":"யார் என்ன செய்கிறார், எப்போதுக்குள் என்று கண்காணித்து, ப்ராஜெக்ட்டை நேரத்திலும் பட்ஜெட்டிலும் வைத்திருப்பவர்.","also":["ப்ராஜெக்ட் மேனேஜர்கள்","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"ரோட்மேப் (வழித்தடம்)","text":"வரும் மாதங்களில் என்ன வரப்போகிறது என்பதற்கான தோராயமான திட்டம், வரிசையாக. இது சரியான தேதிகளை அல்ல, திசையைக் காட்டும்; நீங்கள் கற்றுக்கொள்ளும்போது மாறும்.","also":["ரோட்மேப்கள்","roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"மைல்கல்","text":"“முதல் பதிப்பு வெளியானது” அல்லது “100 பயனர்கள்” போல, ப்ராஜெக்ட்டில் குறித்து வைக்கத் தகுந்த ஒரு புள்ளி.","also":["மைல்கற்கள்","milestone","milestones"]},{"id":"mvp","g":"plan","word":"குறைந்தபட்சப் பயனுள்ள தயாரிப்பு (MVP)","text":"உண்மையான மக்களுக்கு இன்னும் பயனுள்ளதாக இருக்கும், ஒரு தயாரிப்பின் மிகச் சிறிய பதிப்பு; அதனால் அவர்களிடமிருந்து முன்கூட்டியே கற்றுக்கொள்ளலாம்.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"தேவை","text":"முடிந்த தயாரிப்பு கட்டாயம் செய்ய வேண்டிய அல்லது இருக்க வேண்டிய ஒன்று.","also":["தேவைகள்","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"வரம்பு (ஸ்கோப்)","text":"வேலையில் எவை அடங்கும், அதே அளவு முக்கியமாக எவை அடங்காது என்பது.","also":["வேலை வரம்பு","scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"வரம்பு மீறி வளர்தல் (ஸ்கோப் கிரீப்)","text":"கூடுதல் நேரம் அல்லது செலவு பற்றி யாரும் ஒப்புக்கொள்ளாமல், வேலையில் கொஞ்சம் கொஞ்சமாக மேலும் மேலும் சேர்க்கப்பட்டு, அது ஒருபோதும் முடியாமல் போவது.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"அம்சம்","text":"“கடவுச்சொல்லை மீட்டமை” போல, தயாரிப்பு மக்களுக்காகச் செய்யக்கூடிய ஒரு விஷயம்.","also":["அம்சங்கள்","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"எபிக் (பெரிய வேலை)","text":"ஒரே தடவையில் செய்ய முடியாத அளவு பெரிய வேலைத் துண்டு; அதனால் சிறிய கார்டுகளாகப் பிரிக்கப்படும்.","also":["எபிக்கள்","epic","epics"]},{"id":"story","g":"plan","word":"பயனர் கதை (யூசர் ஸ்டோரி)","text":"பயனரின் பக்கத்திலிருந்து எழுதப்பட்ட சிறு வேலை: “ஒரு வாங்குபவராக, என் கூடையைச் சேமிக்க விரும்புகிறேன், பிறகு முடித்துக்கொள்ள.” எதைக் கட்டுவது என்ற உரையாடலை இது தொடங்கி வைக்கும்.","also":["பயனர் கதைகள்","user story","user stories"]},{"id":"ac","g":"plan","word":"ஏற்பு நிபந்தனைகள் (AC)","text":"ஒரு கார்டு முடிந்ததாகக் கருதப்பட அது தாண்ட வேண்டிய சோதனைகள், வேலை தொடங்கும் முன் ஒப்புக்கொள்ளப்பட்டவை; உதாரணமாக “நான் வெளியேறி மீண்டும் உள்நுழைந்த பின்னும் கூடை அப்படியே இருக்கிறது”.","also":["AC","acceptance criteria","ஏற்பு அளவுகோல்"]},{"id":"task","g":"plan","word":"பணி","text":"செய்து முடிக்க வேண்டிய ஒரு தனி வேலை, பெரும்பாலும் ஒரு பெரிய கதையின் ஒரு சிறு படி.","also":["பணிகள்","டாஸ்க்","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"டிக்கெட்","text":"கார்டுக்கு இன்னொரு பெயர்: தொடக்கம் முதல் முடிவு வரை கண்காணிக்கப்படும் ஒரு வேலை அல்லது ஒரு கோரிக்கை.","also":["டிக்கெட்டுகள்","ticket","tickets"]},{"id":"priority","g":"plan","word":"முன்னுரிமை","text":"மற்ற எல்லாவற்றோடும் ஒப்பிடும்போது ஒன்று எவ்வளவு முக்கியம் அல்லது அவசரம் என்பது; அதனால் மிக முக்கியமான வேலை முதலில் நடக்கும்.","also":["முன்னுரிமைகள்","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"முன்னுரிமைப்படுத்துதல்","text":"வேலையை முக்கியத்துவ வரிசையில் வைத்தல். பொதுவான முறை MoSCoW: Must have (கட்டாயம்), Should have (வேண்டும்), Could have (இருந்தால் நல்லது), Won’t have (இந்த முறை இல்லை).","also":["முன்னுரிமை வரிசை","prioritisation","MoSCoW"]},{"id":"estimate","g":"plan","word":"மதிப்பீடு","text":"ஒரு வேலை எவ்வளவு பெரியது அல்லது எவ்வளவு நேரம் ஆகும் என்பதற்கான சிறந்த ஊகம். இது ஊகம்தான், வாக்குறுதி அல்ல.","also":["மதிப்பீடுகள்","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"ஸ்டோரி பாயின்ட்கள்","text":"வேலையின் அளவை மணிநேரத்தில் அல்லாமல், கார்டுகளை ஒன்றோடொன்று ஒப்பிட்டு (“அதைவிட இரண்டு மடங்கு பெரியது”) ஊகிக்கும் முறை. டீம்களை ஒன்றோடொன்று ஒப்பிடுவதற்கு இவை அல்ல.","also":["ஸ்டோரி பாயின்ட்","story points","story point"]},{"id":"tshirt","g":"plan","word":"டி-ஷர்ட் அளவு மதிப்பீடு","text":"வேலையின் அளவை S, M, L அல்லது XL என்று ஊகித்தல். விரைவானது, ஆரம்பத் திட்டமிடலுக்குப் போதுமானது.","also":["டி-ஷர்ட் அளவுகள்","t-shirt sizes","t-shirt sizing"]},{"id":"poker","g":"plan","word":"திட்டமிடல் போக்கர் (பிளானிங் போக்கர்)","text":"மதிப்பிடுவதற்கான ஒரு விளையாட்டு: எல்லோரும் ஒரே நேரத்தில் ஓர் அளவு அட்டையைக் காட்டுவார்கள்; பிறகு அதிகமாகவும் குறைவாகவும் சொன்னவர்கள் ஏன் என்று விளக்குவார்கள்.","also":["planning poker","Scrum poker"]},{"id":"dependency","g":"plan","word":"சார்பு","text":"இன்னொரு வேலை முடியும் வரை, ஒரு வேலையைத் தொடங்கவோ முடிக்கவோ முடியாத நிலை.","also":["சார்புகள்","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"தடை (ப்ளாக்கர்)","text":"பதில் வராமல் இருப்பது அல்லது கருவி பழுதாவது போல, இப்போது வேலை முன்னேறுவதைத் தடுக்கும் எதுவும்.","also":["தடைகள்","blocker","blockers"]},{"id":"deadline","g":"plan","word":"கெடு தேதி","text":"ஒன்று முடிந்திருக்க வேண்டிய தேதி.","also":["கெடு","டெட்லைன்","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"ஒப்படைக்க வேண்டியவை","text":"வேலை உருவாக்கி ஒப்படைக்கும் உறுதியான ஒன்று, வேலை செய்யும் பக்கம் அல்லது அறிக்கை போல.","also":["டெலிவரபிள்","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"முன்கணிப்பு","text":"இதுவரை உங்களுக்குத் தெரிந்ததை வைத்து, வேலை எப்போது முடியும் போன்ற, நடக்க வாய்ப்புள்ளதைப் பற்றிய கணிப்பு.","also":["முன்கணிப்புகள்","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"அளவீடு (மெட்ரிக்)","text":"பக்கப் பார்வைகள் அல்லது ஒரு திருத்தத்துக்கு எவ்வளவு நேரம் ஆகிறது போல, காலப்போக்கில் நீங்கள் அளந்து கண்காணிக்கும் எதுவும்.","also":["அளவீடுகள்","metric","metrics"]},{"id":"feedback","g":"plan","word":"ஃபீட்பேக் (பின்னூட்டம்)","text":"உங்கள் வேலையைப் பற்றி மக்கள் சொல்வது, நல்லதும் கெட்டதும். இதை முன்கூட்டியே, அடிக்கடி பெறுவதுதான் அஜைலின் இதயம்.","noTip":1},{"id":"backlog","g":"agile","word":"பேக்லாக்","text":"இன்னும் திட்டமிடாத ஐடியாக்களும் வேலையும் காத்திருக்கும் பட்டியல், மிக முக்கியமானது மேலே. செய்ய வேண்டியவைக்கு நகரும் வரை அங்கே எதுவும் செய்யப்படாது."},{"id":"sprint","g":"agile","word":"ஸ்பிரிண்ட்","text":"ஓர் இலக்குடனும் முடிக்க ஒப்புக்கொண்ட கார்டுகளுடனும் கூடிய குறுகிய, நிர்ணயிக்கப்பட்ட வேலைக் காலம் (பெரும்பாலும் ஒன்று அல்லது இரண்டு வாரம், ஒரு மாதத்துக்கு மேல் ஒருபோதும் இல்லை).","also":["ஸ்பிரிண்ட்கள்","sprint","sprints"]},{"id":"standup","g":"agile","word":"ஸ்டாண்ட்-அப்","text":"ஒரு விரைவான தினசரிச் சந்திப்பு: ஒவ்வொரு டீம் உறுப்பினரும் என்ன செய்தார், அடுத்து என்ன செய்வார், எது அவரைத் தடுக்கிறது. ஸ்க்ரமில் இதை daily scrum என்பார்கள்.","also":["standup","stand-ups","daily scrum","daily stand-up","தினசரி சந்திப்பு"]},{"id":"kanban","g":"agile","word":"கான்பன்","text":"கார்டுகள் போர்டின் நெடுவரிசைகள் வழியாக (செய்ய வேண்டியவை, நடப்பில், முடிந்தது போல) நகர்ந்து செல்லும், ஒரே நேரத்தில் எவ்வளவு நடப்பில் இருக்கலாம் என்று டீம் வரம்பிடும் வேலை முறை; அதனால் வேலை தடையின்றி ஓடும்."},{"id":"wip","g":"agile","word":"WIP வரம்பு","text":"WIP என்பது work in progress (நடப்பில் உள்ள வேலை) என்பதன் சுருக்கம். WIP வரம்பு என்பது ஒரு நெடுவரிசை ஒரே நேரத்தில் வைத்திருக்கக்கூடிய அதிகபட்ச கார்டுகள்; அதனால் டீம் புதியவற்றைத் தொடங்கும் முன் இருப்பவற்றை முடிக்கும்.","also":["WIP"]},{"id":"dod","g":"agile","word":"முடிந்தது வரையறை","text":"ஒரு கார்டு உங்களிடம் ஒப்படைக்கப்படும் முன், “முடிந்தது” என்றால் என்ன (சோதிக்கப்பட்டது, விளக்கப்பட்டது போல) என்று சொல்லும் குழுவின் சிறு சரிபார்ப்புப் பட்டியல். அதன் இரட்டை, தயார் வரையறை, ஒரு கார்டு தொடங்கும் அளவுக்குத் தெளிவாக எப்போது இருக்கும் என்று சொல்லும்.","also":["Definition of Ready","DoD","DoR","Definition of Done"]},{"id":"retro","g":"agile","word":"ரெட்ரோ","text":"அடுத்த முறை சிறப்பாகச் செய்ய ஒன்றிரண்டு விஷயங்களை முடிவு செய்ய, டீம் எப்படி வேலை செய்கிறது என்று அவ்வப்போது திரும்பிப் பார்த்தல். retrospective என்பதன் சுருக்கம். AI-gile-இல் ரெட்ரோ டீமின் வேலை முறைகளில் ஒரு மாற்றத்தைப் பரிந்துரைக்கும்; நீங்கள் Go அல்லது இன்னும் இல்லை என்று சொல்வீர்கள்.","also":["retro","ரெட்ரோஸ்பெக்டிவ்","retrospective"]},{"id":"swarm","g":"agile","word":"ஸ்வார்ம்","text":"எல்லோரும் ஒன்றுகூடுதல்: ஓர் அவசர விஷயம் தீரும் வரை பலர் மற்ற வேலையை விட்டுவிட்டு அதைச் சேர்ந்து சரிசெய்வார்கள். AI-gile-இல் எல்லா டீம்களும் ஒரே ப்ராஜெக்ட்டில் உதவும், மற்ற ப்ராஜெக்ட்கள் அதுவரை காத்திருக்கும்.","also":["swarm","swarming","திரள்"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"ஸ்க்ரமில், டீம் நன்றாக வேலை செய்ய உதவுபவர்: அவர்களைத் தடுப்பதை நீக்கி, கூட்டங்களைப் பாதையில் வைத்து, நல்ல பழக்கங்களைக் கற்றுத்தருவார்; யாரையும் அதிகாரம் செய்யாமல். AI-gile-இல் Lead Scrum Master, எல்லா ப்ராஜெக்ட்களிலும், சிக்கிய கார்டுகளைக் கண்டுபிடித்து, டீம்களைத் தூண்டி, எது காத்திருக்கிறது என்று உங்களுக்கு நினைவூட்டும்.","also":["Lead Scrum Master","ஸ்க்ரம் மாஸ்டர்"]},{"id":"agile","g":"agile","word":"அஜைல்","text":"சிறு படிகளில் வேலை செய்யும் முறை: கொஞ்சம் கட்டுங்கள், உண்மையான முடிவுகளை அடிக்கடி காட்டுங்கள், மக்கள் சொல்வதிலிருந்து கற்றுக்கொண்டு போகப் போகத் திட்டத்தை மாற்றுங்கள்; எல்லாவற்றையும் முன்கூட்டியே திட்டமிடுவதற்குப் பதிலாக.","also":["Agile development","agile ways of working","Agile"]},{"id":"manifesto","g":"agile","word":"அஜைல் அறிக்கை (Agile Manifesto)","text":"2001-இல் மென்பொருள் உருவாக்குபவர்கள் எழுதிய சிறு அறிக்கை. கனமான திட்டங்களையும் காகித வேலையையும் விட, மனிதர்கள், வேலை செய்யும் முடிவுகள், வாடிக்கையாளர்களுடன் நெருங்கிய வேலை, மாற்றத்துக்கு ஏற்ப நடப்பது ஆகியவற்றை முன்வைக்கிறது.","also":["Agile Manifesto","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"வாட்டர்ஃபால் (நீர்வீழ்ச்சி முறை)","text":"பழைய வேலை முறை: முதலில் எல்லாவற்றையும் திட்டமிடுங்கள், பிறகு எல்லாவற்றையும் கட்டுங்கள், பிறகு எல்லாவற்றையும் சோதியுங்கள், ஒரு கட்டத்துக்குப் பிறகு ஒன்றாக. பிற்பகுதியில் மாற்றுவது கடினம், செலவு அதிகம்.","also":["waterfall model","Waterfall"]},{"id":"iteration","g":"agile","word":"சுற்று (இட்டரேஷன்)","text":"ஒன்றைக் கட்டி, சரிபார்த்து, மேம்படுத்தும் ஒரு சுற்று. அஜைல் வேலை இவற்றின் தொடர்; ஸ்பிரிண்ட் அவற்றில் ஒரு வகை.","also":["சுற்றுகள்","iteration","iterations"]},{"id":"increment","g":"agile","word":"கூடுதல் பகுதி (இன்க்ரிமென்ட்)","text":"ஸ்பிரிண்ட்டிலோ ஒரு சுற்று வேலையிலோ தயாரிப்பில் சேர்க்கப்படும், ஏற்கெனவே இருப்பவற்றுடன் பொருந்தும் புதிய வேலை செய்யும் பகுதி.","also":["இன்க்ரிமென்ட்கள்","increment","increments"]},{"id":"scrum","g":"agile","word":"ஸ்க்ரம்","text":"பிரபலமான அஜைல் வேலை முறை: சிறிய டீம் ஓர் இலக்கை நோக்கிக் குறுகிய ஸ்பிரிண்ட்களில் வேலை செய்யும்; திட்டமிட, சரிபார்க்க, மேம்படுத்த குறிப்பிட்ட பொறுப்புகளும் சில வழக்கமான கூட்டங்களும் இருக்கும்."},{"id":"scrumteam","g":"agile","word":"ஸ்க்ரம் டீம்","text":"ஸ்க்ரமில் வேலை செய்யும் சிறு குழு: ஒரு ப்ராடக்ட் ஓனர், ஒரு ஸ்க்ரம் மாஸ்டர், டெவலப்பர்கள்.","also":["ஸ்க்ரம் டீம்கள்","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"ஸ்க்ரம் நிகழ்வுகள்","text":"ஸ்க்ரமில் உள்ள வழக்கமான கூட்டங்கள்: ஸ்பிரிண்ட் திட்டமிடல், தினசரி ஸ்க்ரம், ஸ்பிரிண்ட் மறுஆய்வு, ரெட்ரோ. பலர் இவற்றை “சடங்குகள்” (ceremonies) என்கிறார்கள்.","also":["சடங்குகள்","ceremonies","Scrum ceremonies","Scrum events"]},{"id":"sprintplan","g":"agile","word":"ஸ்பிரிண்ட் திட்டமிடல்","text":"ஸ்பிரிண்ட் தொடக்கத்தில் நடக்கும் கூட்டம்; இந்த ஸ்பிரிண்ட் ஏன் முக்கியம், எந்த கார்டுகளை எடுப்பது, எப்படித் தொடங்குவது என்பதை டீம் ஒப்புக்கொள்ளும்.","also":["திட்டமிடல் கூட்டம்","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"ஸ்பிரிண்ட் இலக்கு","text":"ஒரு ஸ்பிரிண்ட் எதற்காக என்று சொல்லும் ஒரு வாக்கியம். இலக்கு எட்டப்படும் வரை சிறு பணிகள் வழியில் மாறலாம்.","also":["ஸ்பிரிண்ட் இலக்குகள்","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"ஸ்பிரிண்ட் பேக்லாக்","text":"தற்போதைய ஸ்பிரிண்ட்டுக்குத் தேர்ந்தெடுக்கப்பட்ட கார்டுகள், அவற்றைச் செய்வதற்கான டீமின் திட்டத்துடன்.","also":["sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"ப்ராடக்ட் பேக்லாக்","text":"தயாரிப்புக்காகக் கட்டப்படக்கூடிய எல்லாவற்றின் முழு வரிசைப்படுத்தப்பட்ட பட்டியல், மிக முக்கியமானது மேலே. நீங்கள் புதிதாக அறிந்துகொள்ளும்போதெல்லாம் இது மாறிக்கொண்டே இருக்கும்.","also":["product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"தயாரிப்பு இலக்கு (ப்ராடக்ட் கோல்)","text":"தயாரிப்பு அடைய முயலும் பெரிய விளைவு; அடுத்து என்ன செய்வது என்று தேர்ந்தெடுக்க டீமுக்கு இது உதவும்.","also":["தயாரிப்பு இலக்குகள்","product goal","product goals"]},{"id":"refinement","g":"agile","word":"பேக்லாக் மெருகேற்றம்","text":"கார்டுகளை எடுக்கத் தயாராக்க, பேக்லாக்கை அடிக்கடி பார்த்து ஒழுங்குபடுத்தி, பிரித்து, வரிசைப்படுத்தி, விவரம் சேர்த்தல். பேக்லாக் க்ரூமிங் என்றும் சொல்வார்கள்.","also":["backlog refinement","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"ஸ்பிரிண்ட் மறுஆய்வு","text":"ஸ்பிரிண்ட் முடிவில் நடக்கும் கூட்டம்; டீம் முடித்ததைக் காட்டி, மக்கள் என்ன நினைக்கிறார்கள் என்று கேட்டு, அடுத்து என்ன என்று முடிவு செய்யும்.","also":["sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"டெமோ (செயல்விளக்கம்)","text":"முடிந்த வேலை செயல்படுவதை, கேட்டவர்களுக்கு நேரடியாகக் காட்டுதல்.","also":["டெமோக்கள்","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"நேர வரம்பு (டைம்பாக்ஸ்)","text":"ஒன்றுக்கு நிர்ணயிக்கப்பட்ட நேரம். அது தீர்ந்ததும், எல்லாம் முடியாவிட்டாலும் நிறுத்திவிடுவீர்கள்.","also":["timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"வேகம் (வெலாசிட்டி)","text":"ஒரு டீம் வழக்கமாக ஒரு ஸ்பிரிண்ட்டில் எவ்வளவு வேலை முடிக்கிறது என்பது; அடுத்த முறை எவ்வளவு எடுப்பது என்று திட்டமிடப் பயன்படும். மக்கள் எவ்வளவு கடினமாக உழைக்கிறார்கள் என்பதற்கான மதிப்பெண் இது அல்ல.","also":["velocity","team velocity"]},{"id":"capacity","g":"agile","word":"திறன் அளவு (கொள்ளளவு)","text":"விடுமுறைகள், பிற வேலைகள் போக, ஒரு காலத்தில் டீம் எவ்வளவு வேலை எடுத்துக்கொள்ள முடியும் என்பது.","noTip":1},{"id":"burndown","g":"agile","word":"பர்ன்டவுன் வரைபடம்","text":"ஒரு ஸ்பிரிண்ட்டில் மீதமுள்ள வேலை நாளுக்கு நாள் குறைவதைக் காட்டும் வரைபடம். கோடு தட்டையாகவே இருந்தால், ஏதோ சிக்கியிருக்கிறது.","also":["burndown","burndown chart","burn-down chart"]},{"id":"burnup","g":"agile","word":"பர்ன்அப் வரைபடம்","text":"திட்டமிட்ட மொத்தத்தின் அருகே, காலப்போக்கில் முடிந்த வேலை உயர்வதைக் காட்டும் வரைபடம்; எப்போது அங்கே சேர்வீர்கள் என்று பார்க்கலாம்.","also":["burnup","burnup chart","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"கான்பன் போர்டு","text":"போர்டே இதுதான்: வேலையின் ஒவ்வொரு கட்டத்துக்கும் ஒரு நெடுவரிசை, கார்டுகள் குறுக்கே நகரும்.","also":["Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"இழுக்கும் முறை (புல் சிஸ்டம்)","text":"ஏற்கெனவே நிறைய இருப்பவர் மேல் வேலையைத் திணிக்காமல், யாருக்காவது இடம் இருக்கும்போது மட்டுமே புதிய வேலை தொடங்கும் வேலை முறை.","also":["pull system","pull-based"]},{"id":"flow","g":"agile","word":"ஓட்டம் (ஃப்ளோ)","text":"போர்டில் வேலை எவ்வளவு சீராக நகர்கிறது என்பது. நல்ல ஓட்டம் என்றால் கார்டுகள் குவியாமல் நகர்ந்துகொண்டே இருக்கும்.","also":["வேலை ஓட்டம்","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"லீட் டைம் (கோரிக்கை முதல் முடிவு வரை)","text":"ஒருவர் ஒன்றைக் கேட்டதிலிருந்து அது முடியும் வரை எவ்வளவு நேரம் ஆகிறது என்பது.","also":["lead time","lead times"]},{"id":"cycletime","g":"agile","word":"சைக்கிள் டைம் (சுழற்சி நேரம்)","text":"ஒரு கார்டில் உண்மையாக வேலை தொடங்கியதிலிருந்து முடியும் வரை எவ்வளவு நேரம் ஆகிறது என்பது.","also":["cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"முடிக்கும் அளவு (த்ரூபுட்)","text":"ஒரு வாரத்தில் அல்லது எந்தக் குறிப்பிட்ட நேரத்தில் எத்தனை கார்டுகள் முடிகின்றன என்பது.","also":["throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"தடைக்கல் (பாட்டில்நெக்)","text":"பாட்டிலின் குறுகிய கழுத்து போல, வேலை குவிந்து அதன் பின்னால் உள்ள எல்லாவற்றையும் மெதுவாக்கும் ஒரு கட்டம்.","also":["bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"ஸ்விம்லேன்","text":"அவசர வேலை அல்லது ஒரு டீமின் கார்டுகள் போல, ஒரே வகைக் கார்டுகளைத் தொகுக்கும் போர்டின் குறுக்கு வரிசை.","also":["swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"லீன்","text":"வீண் செயல்களை (வாடிக்கையாளருக்கு உதவாத எதையும்) நீக்கி, வேலையைத் தடையின்றி ஓடவைக்கும் வேலை முறை."},{"id":"waste","g":"agile","word":"வீண் (வேஸ்ட்)","text":"லீனில், முயற்சி எடுக்கும் ஆனால் வாடிக்கையாளருக்கு உதவாத எதுவும்; காத்திருப்பது, மறுவேலை, யாரும் பயன்படுத்தாதவற்றைக் கட்டுவது போல.","noTip":1},{"id":"kaizen","g":"agile","word":"தொடர் மேம்பாடு","text":"சிறிய, வழக்கமான மாற்றங்கள் மூலம் எப்போதும் கொஞ்சம் கொஞ்சமாக மேம்படுதல், பிறகு அவை உதவினவா என்று சரிபார்த்தல். ரெட்ரோக்கள் இதற்கான ஒரு வழி. கைசென் என்றும் சொல்வார்கள்.","also":["kaizen","கைசென்","continuous improvement"]},{"id":"selforg","g":"agile","word":"தானே ஒழுங்கமைக்கும் டீம்","text":"படிப்படியாகச் சொல்லப்படாமல், வேலையை எப்படிச் செய்வது என்று தானே முடிவு செய்யும் டீம்.","also":["தானே நிர்வகிக்கும் டீம்","self-organising","self-organising team","self-managing team"]},{"id":"crossfunc","g":"agile","word":"பல்திறன் டீம்","text":"வடிவமைப்பு, கட்டுதல், சோதனை போன்ற, வேலையைத் தானே முடிக்கத் தேவையான எல்லாத் திறமைகளும் உள்ள டீம்.","also":["cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"ஸ்பைக் (குறுகிய ஆய்வு)","text":"உண்மையான வேலையில் இறங்கும் முன் ஒரு கேள்விக்குப் பதில் காண, நேர வரம்புடன் செய்யும் சிறு ஆய்வு.","also":["spike","spikes"]},{"id":"rework","g":"agile","word":"மறுவேலை","text":"முதல் முறை சரியாக இல்லாததால் வேலையை மீண்டும் செய்தல்.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"பெரிய அளவிலான அஜைல் (SAFe)","text":"பெரிய நிறுவனத்தில் பல டீம்களில் அஜைலைப் பயன்படுத்தும் முறைகள். SAFe (Scaled Agile Framework) அதற்கு நன்கு அறியப்பட்ட ஓர் எடுத்துக்காட்டு.","also":["scaled Agile","Scaled Agile"]},{"id":"repo","g":"build","word":"ரெப்போ","text":"கமிட்களின் முழு வரலாற்றுடன் கூடிய ப்ராஜெக்ட்டின் கோடு கோப்புறை. இது உங்கள் கணினியில், GitHub-இல் அல்லது இரண்டிலும் இருக்கலாம்.","also":["ரெபாசிட்டரி","repo","repository"]},{"id":"branch","g":"build","word":"பிராஞ்ச்","text":"கோடில் தனி வேலைக் கிளை, அதனால் முதன்மைப் பதிப்பைத் தொடாமல் மாற்றங்கள் செய்யலாம்.","also":["பிராஞ்சுகள்","branch","branches"]},{"id":"commit","g":"build","word":"கமிட்","text":"கோடின் சேமிக்கப்பட்ட ஒரு ஸ்னாப்ஷாட், என்ன மாறியது என்ற சிறு குறிப்புடன். எப்போது வேண்டுமானாலும் ஒன்றுக்குத் திரும்பிப் போகலாம்.","also":["கமிட்கள்","commit","commits"]},{"id":"push","g":"build","word":"புஷ்","text":"சேமித்த உங்கள் ஸ்னாப்ஷாட்களை (கமிட்கள்) இந்தக் கணினியிலிருந்து GitHub போன்ற இணையப் பகிர்வு நகலுக்கு அனுப்புதல்; அதனால் அவை காப்புப் பிரதி எடுக்கப்பட்டு மற்றவர்களும் பெறலாம்."},{"id":"merge","g":"build","word":"மெர்ஜ்","text":"ஒரு பிராஞ்சின் மாற்றங்களை இன்னொன்றில், பெரும்பாலும் மீண்டும் முதன்மைப் பதிப்பில் சேர்த்தல்."},{"id":"pr","g":"build","word":"புல் ரிக்வெஸ்ட்","text":"ஒரு பிராஞ்சின் மாற்றங்களைச் சரிபார்த்து முதன்மைப் பதிப்பில் இணைக்கும்படி கேட்பது. சில தளங்கள் இதை merge request என்பார்கள்.","also":["PR","PRs","merge request","இழுப்புக் கோரிக்கை"]},{"id":"refactor","g":"build","word":"ரீஃபாக்டர்","text":"கோடு செய்வதை மாற்றாமல் அதைச் சீர்செய்வது: சிறிய கோப்புகள், தெளிவான பெயர்கள், குறைவான திரும்பத் திரும்ப எழுதிய கோடு."},{"id":"bug","g":"build","word":"பக்","text":"இருக்க வேண்டியபடி வேலை செய்யாத ஒன்று.","also":["பக்குகள்","bug","bugs"]},{"id":"peerreview","g":"build","word":"சக மதிப்பாய்வு","text":"இன்னொரு ஜோடிக் கண்கள்: வேலை உங்களை அடையும் முன், எழுதியவர் அல்லாத வேறொருவர் அதைச் சரிபார்ப்பார்; அதனால் குறைவான தவறுகளே கடந்து செல்லும். AI-gile-இல் ஒவ்வொரு கார்டையும் இன்னொரு AI சரிபார்க்கும்.","also":["peer review","பீர் ரிவ்யூ","code review"]},{"id":"code","g":"build","word":"கோடு (நிரல்)","text":"கணினிக்கு என்ன செய்ய வேண்டும் என்று சொல்லும் எழுதப்பட்ட அறிவுறுத்தல்கள். மூலக் குறியீடு (source code) என்றும் சொல்வார்கள்.","also":["நிரல்","code","source code","மூலக் குறியீடு"],"noTip":1},{"id":"proglang","g":"build","word":"நிரலாக்க மொழி","text":"JavaScript, Python, Java போல, கோடு எழுதப் பயன்படும் மொழி. வெவ்வேறு வேலைகளுக்கு வெவ்வேறு மொழிகள் பொருந்தும்.","also":["நிரலாக்க மொழிகள்","programming language","programming languages"]},{"id":"developer","g":"build","word":"டெவலப்பர் (dev)","text":"கோடு எழுதி மாற்றுபவர். புரோகிராமர் அல்லது மென்பொருள் பொறியாளர் என்றும் சொல்வார்கள்.","also":["டெவலப்பர்கள்","developer","developers","programmer","programmers","software engineer","நிரலர்"]},{"id":"software","g":"build","word":"மென்பொருள்","text":"இயந்திரங்களுக்கு (ஹார்டுவேர்) மாறாக, கணினிகளிலும் போன்களிலும் ஓடும் புரோகிராம்கள்.","noTip":1},{"id":"app","g":"build","word":"ஆப்","text":"அப்ளிகேஷன் என்பதன் சுருக்கம்: போன், கணினி அல்லது இணைய உலாவியில், ஒரு காரியத்தைச் செய்து முடிக்க மக்கள் பயன்படுத்தும் புரோகிராம்.","also":["ஆப்கள்","செயலி","app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"வலை ஆப்","text":"இணைய உலாவியில் ஓடும் ஆப்; அதனால் நிறுவ எதுவும் இல்லை.","also":["வலை ஆப்கள்","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"ஃப்ரண்ட் எண்ட் (முன்பக்கம்)","text":"நீங்கள் பார்த்து அழுத்தும் ஆப்பின் பகுதி: திரைகள், பொத்தான்கள், சொற்கள், பெரும்பாலும் உங்கள் உலாவியில்.","also":["front end","front-end","frontend"]},{"id":"backend","g":"build","word":"பேக் எண்ட் (பின்பக்கம்)","text":"தரவைச் சேமித்து வைத்து, நீங்கள் எதையாவது அழுத்தும்போது, கடவுச்சொல்லைச் சரிபார்ப்பது போல, வேலை செய்யும் ஆப்பின் திரைக்குப் பின்னால் உள்ள பகுதி.","also":["back end","back-end","backend"]},{"id":"fullstack","g":"build","word":"ஃபுல் ஸ்டாக்","text":"ஃப்ரண்ட் எண்ட், பேக் எண்ட் இரண்டிலும் வேலை செய்தல்.","also":["full stack","full-stack"]},{"id":"ui","g":"build","word":"பயனர் இடைமுகம் (UI)","text":"திரையில் ஒருவர் பார்த்துப் பயன்படுத்துவது: அமைப்பு, பொத்தான்கள், மெனுக்கள், எழுத்து.","also":["UI","user interface","இடைமுகம்"]},{"id":"ux","g":"build","word":"பயனர் அனுபவம் (UX)","text":"ஒன்றைப் பயன்படுத்தும்போது எப்படி இருக்கிறது என்பது: எளிதாக, தெளிவாக, இனிமையாக அல்லது குழப்பமாக, மெதுவாக.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"அணுகல்தன்மை (a11y)","text":"நன்றாகப் பார்க்க முடியாதவர்கள், மவுஸ் பயன்படுத்த முடியாதவர்கள், ஸ்கிரீன் ரீடர் பயன்படுத்துபவர்கள் உட்பட எல்லோரும் பயன்படுத்தும்படி செய்தல்.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"தகவமையும் வடிவமைப்பு (ரெஸ்பான்சிவ்)","text":"போன் முதல் பெரிய மானிட்டர் வரை, எந்தத் திரை அளவிலும் பக்கங்கள் பொருந்தி நன்றாக வேலை செய்யும்படி செய்தல்.","also":["responsive design"]},{"id":"designsys","g":"build","word":"வடிவமைப்பு அமைப்பு (டிசைன் சிஸ்டம்)","text":"நிறங்கள், எழுத்துருக்கள், பொத்தான்கள், விதிகள் அடங்கிய பகிரப்பட்ட தொகுப்பு; அதனால் ஒவ்வொரு திரையும் ஒரே மாதிரித் தோன்றி ஒரே மாதிரி நடந்துகொள்ளும்.","also":["design system","design systems"]},{"id":"architecture","g":"build","word":"கட்டமைப்பு (ஆர்க்கிடெக்சர்)","text":"ஒரு அமைப்பின் ஒட்டுமொத்த வடிவம்: முக்கியப் பகுதிகள் என்ன, அவை ஒன்றோடொன்று எப்படிப் பேசுகின்றன."},{"id":"database","g":"build","word":"தரவுத்தளம் (DB)","text":"தகவல்களின் ஒழுங்கான சேமிப்பிடம்; ஆப் படிக்கவும் மாற்றவும் முடிகிற மிகவும் ஆற்றல்மிக்க விரிதாள் போல.","also":["தரவுத்தளங்கள்","database","databases","DB","டேட்டாபேஸ்"]},{"id":"schema","g":"build","word":"தரவுத்தள வடிவமைப்பு (ஸ்கீமா)","text":"தரவுத்தளத்தின் அமைப்பு: அதில் என்னென்ன தகவல் அட்டவணைகள் உள்ளன, ஒவ்வொன்றிலும் என்ன போகும் என்பது.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"structured query language என்பதன் சுருக்கம்: பல தரவுத்தளங்களிடம் தகவல் கேட்கவோ மாற்றவோ பயன்படும் மொழி.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"தரவு (டேட்டா)","text":"பெயர்கள், ஆர்டர்கள், அமைப்புகள் போல கணினி வைத்திருக்கும் தகவல்.","also":["data","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"சர்வர்","text":"எப்போதும் இயங்கிக்கொண்டிருந்து, நீங்கள் ஒரு வலைப்பக்கத்துக்குச் செல்லும்போது அதை அனுப்புவது போல, மற்ற கணினிகளின் கோரிக்கைகளுக்குப் பதிலளிக்கும் கணினி.","also":["சர்வர்கள்","server","servers"]},{"id":"client","g":"build","word":"கிளையன்ட்","text":"சர்வரிடம் பேசி ஒன்றைக் கேட்கும் பக்கம், பொதுவாக உங்கள் உலாவி அல்லது ஆப். வணிகத்தில் இது வெறும் வாடிக்கையாளரையும் குறிக்கும்.","also":["கிளையன்ட்கள்","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"application programming interface என்பதன் சுருக்கம்: வானிலை சேவையிடம் இன்றைய முன்னறிவிப்பைக் கேட்பது போல, ஒரு புரோகிராம் இன்னொன்றிடம் வைக்கக்கூடிய கோரிக்கைகளின் நிலையான பட்டியல்.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"எண்ட்பாயின்ட்","text":"API-யின் பட்டியலில் ஒரு உருப்படி: ஒரு புரோகிராம் எதையாவது பெற அல்லது அனுப்ப அழைக்கக்கூடிய இணைய முகவரி.","also":["endpoint","endpoints"]},{"id":"integration","g":"build","word":"ஒருங்கிணைப்பு","text":"உங்கள் கடை ஆர்டர்களை உங்கள் கணக்கு மென்பொருளுக்கு அனுப்புவது போல, இரண்டு அமைப்புகள் சேர்ந்து வேலை செய்ய இணைத்தல்.","also":["ஒருங்கிணைப்புகள்","integration","integrations"]},{"id":"webhook","g":"build","word":"வெப்ஹூக்","text":"“பணம் வந்தது” போல ஏதாவது நடக்கும் நொடியில் ஓர் அமைப்பு தானாகவே இன்னொன்றுக்கு அனுப்பும் செய்தி.","also":["வெப்ஹூக்குகள்","webhook","webhooks"]},{"id":"library","g":"build","word":"நூலகம் (லைப்ரரி)","text":"வேறொருவர் எழுதிய, நீங்களே எழுதாமல் மீண்டும் பயன்படுத்தக்கூடிய தயார் கோடு.","also":["நூலகங்கள்","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"ஃப்ரேம்வொர்க்","text":"நீங்கள் நிரப்பும் வீட்டுச் சட்டகம் போல, கோடு எப்படி அமைய வேண்டும் என்பதில் பெரும்பகுதியை முடிவு செய்யும், ஆப் கட்டுவதற்கான தயார் அமைப்பு.","also":["ஃப்ரேம்வொர்க்குகள்","framework","frameworks"]},{"id":"sdk","g":"build","word":"மென்பொருள் உருவாக்கக் கருவித்தொகுப்பு (SDK)","text":"ஒரு தளத்துக்கோ சேவைக்கோ மென்பொருள் கட்டுவதற்கான கருவிகள், கோடு, எடுத்துக்காட்டுகள் அடங்கிய பெட்டி.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"மென்பொருள் சார்புகள்","text":"உங்கள் கோடு வேலை செய்ய அதற்குத் தேவையான ஒரு லைப்ரரி அல்லது கருவி. பாதுகாப்புக்காக இவற்றைப் புதுப்பித்து வைத்திருப்பது முக்கியம்.","also":["software dependency","software dependencies"]},{"id":"package","g":"build","word":"தொகுப்பு (பேக்கேஜ்)","text":"ஒரு ப்ராஜெக்ட்டில் நிறுவிப் பயன்படுத்தக்கூடிய தயார் கோடின் தொகுப்பு.","also":["தொகுப்புகள்","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"பேக்கேஜ் மேனேஜர்","text":"உங்கள் கோடு சார்ந்திருக்கும் பேக்கேஜ்களைக் கொண்டுவந்து புதுப்பிக்கும் கருவி. npm பொதுவான ஒன்று.","also":["package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"கோடு மாற்றங்களின் வரலாற்றை, கமிட்கள் மற்றும் பிராஞ்சுகள் வடிவில், பேணுவதற்குப் பரவலாகப் பயன்படும் கருவி."},{"id":"github","g":"build","word":"GitHub","text":"Git ரெப்போக்களை இணையத்தில் வைத்திருக்கும் இணையதளம்; அதனால் டீம்கள் கோடைப் பகிர்ந்து, மாற்றங்களை ஆய்வு செய்து, வேலையைக் கண்காணிக்கலாம்."},{"id":"vcs","g":"build","word":"பதிப்புக் கட்டுப்பாடு (வெர்ஷன் கன்ட்ரோல்)","text":"கோப்புகளில் செய்யப்பட்ட ஒவ்வொரு மாற்றத்தின் முழு வரலாற்றையும் வைத்திருத்தல்; அதனால் யார் எதை மாற்றினார் என்று பார்க்கவும், தேவைப்பட்டால் பின்னோக்கிச் செல்லவும் முடியும். Git இதைச் செய்கிறது.","also":["version control","source control","version control system","பதிப்பு கட்டுப்பாடு"]},{"id":"clone","g":"build","word":"க்ளோன்","text":"ஒரு ரெப்போவின் வரலாற்றுடன் கூடிய உங்களுக்கான முழு நகலை உங்கள் கணினியில் உருவாக்குதல்.","also":["clone","cloned","cloning"]},{"id":"pull","g":"build","word":"புல் (இழுத்தல்)","text":"பகிரப்பட்ட நகலிலிருந்து (GitHub போல) சமீபத்திய கமிட்களை உங்கள் கணினிக்குக் கொண்டுவருதல். புஷ்ஷுக்கு எதிரானது.","also":["pull","git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"முதன்மைக் கிளை (மெயின் பிராஞ்ச்)","text":"எல்லோரும் தங்கள் வேலையைத் தொடங்கும் கோடின் அதிகாரப்பூர்வ பதிப்பு; பெரும்பாலும் main அல்லது master என்று அழைக்கப்படும்.","also":["main branch","master branch"]},{"id":"conflict","g":"build","word":"மெர்ஜ் முரண்பாடு","text":"இரண்டு மாற்றங்கள் ஒரே வரிகளைத் தொடும்போது, வெவ்வேறு விதமாக இருப்பதால் கணினியால் அவற்றை இணைக்க முடியாமல், ஒரு மனிதர் தேர்ந்தெடுக்க வேண்டிய நிலை.","also":["merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"டிஃப் (வேறுபாடு)","text":"இரண்டு பதிப்புகளுக்கிடையே சரியாக என்ன மாறியது என்று காட்டும் பார்வை: சேர்க்கப்பட்ட வரிகளும் நீக்கப்பட்ட வரிகளும்.","also":["diff","diffs"]},{"id":"fork","g":"build","word":"ஃபோர்க்","text":"வேறொருவரின் ரெப்போவின் உங்களுக்கான சொந்த நகல்; அவருடையதைப் பாதிக்காமல் இதை மாற்றலாம்.","also":["fork","forks","forked"]},{"id":"script","g":"build","word":"ஸ்கிரிப்ட்","text":"கோப்புகளை ஒழுங்குபடுத்துவது அல்லது ஆப்பைத் தொடங்குவது போல, தானாகவே ஒரு வேலையைச் செய்யும் சிறு புரோகிராம்.","also":["ஸ்கிரிப்ட்கள்","script","scripts"],"noTip":1},{"id":"build","g":"build","word":"பில்ட் (கட்டுதல்)","text":"கோடை ஓடத் தயாரான ஒன்றாக மாற்றுதல், அல்லது ஓடத் தயாரான அந்த விளைவே.","also":["build","builds"],"noTip":1},{"id":"compile","g":"build","word":"காம்பைல் (தொகுத்தல்)","text":"மனிதர்கள் எழுதிய கோடைக் கணினி நேரடியாக ஓட்டக்கூடிய வடிவமாக மொழிபெயர்த்தல்.","also":["compile","compiler"]},{"id":"cli","g":"build","word":"கட்டளை வரி (CLI)","text":"கிளிக் செய்வதற்குப் பதிலாக, கணினிக்கான அறிவுறுத்தல்களை நீங்கள் தட்டச்சு செய்யும் எழுத்துச் சாளரம். டெர்மினல் என்றும் சொல்வார்கள்.","also":["கட்டளை வரி","command line","command-line","CLI","terminal","டெர்மினல்"]},{"id":"config","g":"build","word":"உள்ளமைவு (config)","text":"மென்பொருள் எப்படி நடந்துகொள்ளும் என்பதைக் கட்டுப்படுத்தும் அமைப்புகள்; மாற்றுவது எளிதாக இருக்க கோடிலிருந்து தனியே வைக்கப்படும்.","also":["config","configuration","கான்ஃபிக்"],"noTip":1},{"id":"envvar","g":"build","word":"சூழல் மாறி (என்விரான்மென்ட் வேரியபிள்)","text":"ஒரு புரோகிராம் தொடங்கும்போது அதனிடம் கொடுக்கப்படும் அமைப்பு; முகவரிகள், கடவுச்சொற்கள் கோடில் எழுதப்படாமல் இருக்க இது பெரும்பாலும் பயன்படும்.","also":["environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"டிபக்கிங் (பிழை நீக்கம்)","text":"ஏதாவது ஏன் வேலை செய்யவில்லை என்று தேடிக் கண்டுபிடித்து, சரிசெய்தல்.","also":["debugging","debug","debugged"]},{"id":"pairing","g":"build","word":"ஜோடி நிரலாக்கம் (பேர் புரோகிராமிங்)","text":"இரண்டு பேர் (அல்லது ஒருவரும் ஒரு AI-யும்) ஒரே கோடில் சேர்ந்து வேலை செய்தல்; ஒருவர் தட்டச்சு செய்ய, மற்றவர் சரிபார்ப்பார்.","also":["pair programming","pairing"]},{"id":"docs","g":"build","word":"ஆவணங்கள் (docs)","text":"ஒன்று எப்படி வேலை செய்கிறது அல்லது எப்படிப் பயன்படுத்துவது என்பதற்கான எழுத்து விளக்கங்கள்.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"ஒரு ரெப்போவில் முதலில் படிக்க வேண்டிய கோப்பு: ப்ராஜெக்ட் என்ன, அதை எப்படி இயக்குவது.","also":["READMEs"]},{"id":"legacy","g":"build","word":"பழைய அமைப்பு (லெகசி)","text":"இன்னும் பயன்பாட்டில் இருக்கும், ஆனால் மாற்றுவது கடினமான பழைய அமைப்பு; பெரும்பாலும் இப்போது வெகு சிலருக்கே அது புரியும் என்பதால்.","also":["legacy system","legacy systems","legacy code","பழைய கோடு"]},{"id":"techdebt","g":"build","word":"தொழில்நுட்பக் கடன் (டெக் டெப்ட்)","text":"இப்போது நேரத்தைச் சேமித்து, பிற்கால மாற்றங்களை மெதுவாக்கும் குறுக்குவழிகள்; வட்டி சேரும் கடன் போல. ரீஃபேக்டரிங் அதைக் குறைக்கும்.","also":["technical debt","tech debt"]},{"id":"test","g":"test","word":"டெஸ்ட்","text":"ஒன்று இருக்க வேண்டியபடி வேலை செய்கிறதா என்ற சரிபார்ப்பு. சில சோதனைகளைக் கோடு மாறும் ஒவ்வொரு முறையும் கணினி தானாகவே ஓட்டும்; மற்றவை, முடிந்த கார்டை ஏற்கும் முன் நீங்களே முயன்று பார்ப்பது.","also":["டெஸ்ட்கள்","test","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"quality assurance (தர உறுதி) என்பதன் சுருக்கம்: வேலை நேரலைக்குப் போகும் முன் சரியாக இருப்பதை உறுதிசெய்யச் செய்யும் அனைத்தும். AI-gile-இல் அது தானியங்கிச் சரிபார்ப்புகளைக் குறிக்கும்: QA சிவப்பாக இருந்தால் ஏதோ தோற்றது, அது சரிசெய்யப்படும் வரை நேரலைக்குப் போக முடியாது.","also":["தரச் சோதனை","தரச் சோதனைகள்","தர உறுதி"]},{"id":"testpile","g":"test","word":"சோதனைக் குவியல்","text":"நீங்கள் முயன்று பார்க்கக் காத்திருக்கும் முடிந்த கார்டுகள், ஒன்றன்பின் ஒன்றாக. ஒன்றை ஏற்றுக்கொள்ளுங்கள் அல்லது ஒரு குறிப்புடன் திருப்பி அனுப்புங்கள், அடுத்தது வரும்.","also":["சோதனைக் குவியல்கள்"]},{"id":"autotest","g":"test","word":"தானியங்கிச் சோதனை","text":"தவறுகளை முன்கூட்டியே பிடிக்க, கோடு மாறும் ஒவ்வொரு முறையும் கணினி தானாகவே ஓட்டும் சரிபார்ப்பு.","also":["தானியங்கிச் சோதனைகள்","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"கைமுறைச் சோதனை","text":"வேலை சரியாக நடந்துகொள்கிறதா என்று ஒரு நபர் கையால் முயன்று பார்த்தல்.","also":["கைமுறைச் சோதனைகள்","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"யூனிட் சோதனை","text":"கோடின் ஒரு சிறு பகுதியை மட்டும் தனியாகச் சரிபார்க்கும் சிறிய தானியங்கிச் சோதனை.","also":["unit test","unit tests"]},{"id":"integtest","g":"test","word":"ஒருங்கிணைப்புச் சோதனை","text":"ஒவ்வொன்றாக அல்லாமல், பல பகுதிகள் சேர்ந்து சரியாக வேலை செய்கின்றனவா என்ற சரிபார்ப்பு.","also":["integration test","integration tests"]},{"id":"endtoend","g":"test","word":"முனைக்கு முனை சோதனை (E2E)","text":"பதிவு செய்தல், வாங்குதல், பணம் செலுத்துதல் போல, தொடக்கம் முதல் முடிவு வரை உண்மையான பயனரைப் போல நடந்துகொள்ளும் சோதனை.","also":["E2E","end-to-end tests","end-to-end test"]},{"id":"uat","g":"test","word":"பயனர் ஏற்புச் சோதனை (UAT)","text":"வேலையைக் கேட்டவர்களே அதைப் பயன்படுத்திப் பார்த்து, தங்களுக்குத் தேவையானதைச் செய்கிறதா என்று சொல்வார்கள். AI-gile-இன் சோதனைக் குவியல் இதன் வடிவம்.","also":["UAT","acceptance testing","user acceptance testing"]},{"id":"regression","g":"test","word":"ரிக்ரஷன் (பின்னடைவு)","text":"முன்பு வேலை செய்து, ஒரு மாற்றத்துக்குப் பிறகு உடைந்துபோன ஒன்று. பழையவை இன்னும் வேலை செய்கின்றனவா என்று ரிக்ரஷன் சோதனைகள் பார்க்கும்.","also":["regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"ஸ்மோக் சோதனை (புகைச் சோதனை)","text":"எடுத்துக்காட்டாக ஒரு மாற்றம் நேரலைக்கு வந்த உடனே, முக்கியமானவை அடிப்படையிலாவது வேலை செய்கின்றனவா என்று பார்க்கும் மிக விரைவான சரிபார்ப்பு. தோற்றால் நிறுத்தி ஆராயுங்கள்.","also":["smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"ஆராய்ச்சிச் சோதனை","text":"திட்டமிட்ட சோதனைகள் தவறவிடும் பிரச்சினைகளைக் கண்டுபிடிக்க, தயாரிப்பைச் சுதந்திரமாக வெவ்வேறு விதங்களில் குத்திப் பார்த்தல்.","also":["exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"சோதனை நிலை (டெஸ்ட் கேஸ்)","text":"முயன்று பார்க்க எழுதப்பட்ட ஒரு சூழல்: படிகளும், என்ன நடக்க வேண்டும் என்பதும்.","also":["test case","test cases"]},{"id":"coverage","g":"test","word":"சோதனை உள்ளடக்கம் (டெஸ்ட் கவரேஜ்)","text":"கோடில் எவ்வளவு தானியங்கிச் சோதனைகளால் சரிபார்க்கப்படுகிறது என்பது. அதிகம் என்றால் பொதுவாகப் பாதுகாப்பு அதிகம்; ஆனால் அதிக கவரேஜ் மட்டுமே அது நன்றாக வேலை செய்கிறது என்பதை நிரூபிக்காது.","also":["test coverage","code coverage"]},{"id":"testdata","g":"test","word":"சோதனைத் தரவு","text":"சோதிக்கும்போது பயன்படுத்தும் கற்பனை எடுத்துக்காட்டுத் தகவல்; அதனால் எந்த உண்மையான நபரின் தனிப்பட்ட விவரமும் வெளிப்படாது.","also":["test data","test fixtures"]},{"id":"edgecase","g":"test","word":"விளிம்பு நிலை (எட்ஜ் கேஸ்)","text":"காலியான படிவம் அல்லது ஒற்றை மேற்கோள் குறியுள்ள பெயர் போல, எல்லைகளில் உள்ள அசாதாரண நிலை; அங்கே பெரும்பாலும் விஷயங்கள் உடையும்.","also":["edge case","edge cases"]},{"id":"happypath","g":"test","word":"மகிழ்ச்சிப் பாதை (ஹேப்பி பாத்)","text":"எல்லாம் சரியாக நடக்கும் வழக்கமான வழி. நல்ல சோதனை மகிழ்ச்சியற்ற பாதைகளையும் முயன்று பார்க்கும்."},{"id":"perftest","g":"test","word":"செயல்திறன் சோதனை","text":"ஒன்று எவ்வளவு வேகமானது, நெருக்கடியில் எவ்வளவு நன்றாகச் சமாளிக்கிறது என்று சரிபார்த்தல்.","also":["performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"சுமைச் சோதனை","text":"நிறைய பேர் ஒரே நேரத்தில் பயன்படுத்தும்போது ஓர் அமைப்பு எப்படிச் சமாளிக்கிறது என்று சரிபார்த்தல்.","also":["load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"பாதுகாப்புச் சோதனை","text":"ஒருவர் அமைப்பைத் தவறாகப் பயன்படுத்தவோ, பார்க்கக் கூடாததைப் பார்க்கவோ வழிவிடும் பலவீனங்களைத் தேடுதல்.","also":["security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"அணுகல்தன்மைச் சோதனை","text":"ஸ்கிரீன் ரீடர் அல்லது விசைப்பலகை மட்டும் பயன்படுத்துபவர்கள் உட்பட, வெவ்வேறு திறன் உள்ளவர்கள் தயாரிப்பைப் பயன்படுத்த முடிகிறதா என்று சரிபார்த்தல்.","also":["accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"லிண்டிங்","text":"புரோகிராம்களுக்கான எழுத்துப்பிழை சரிபார்ப்பி போல, கோடில் இருக்கக்கூடிய தவறுகளையும் ஒழுங்கற்ற பாணியையும் கண்டுபிடிக்கும் தானியங்கிச் சரிபார்ப்பு.","also":["linting","linter","lint"]},{"id":"static","g":"test","word":"நிலையான பகுப்பாய்வு (ஸ்டாட்டிக் அனாலிசிஸ்)","text":"கோடை ஓட்டாமல், தானாகவே படிப்பதன் மூலம் பிரச்சினைகளைக் கண்டுபிடித்தல்.","also":["static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"நிலையற்ற சோதனை (ஃபிளேக்கி டெஸ்ட்)","text":"தெளிவான காரணமின்றி சில சமயம் தேறி, சில சமயம் தோற்கும் சோதனை; அதனால் முழுமையாக நம்ப முடியாது.","also":["flaky test","flaky tests"]},{"id":"repro","g":"test","word":"மீண்டும் நிகழ்த்துதல் (repro)","text":"அதே படிகளைப் பின்பற்றி ஒரு பக்கை வேண்டுமென்றே மீண்டும் நடக்கச் செய்தல்; அதனால் அதை ஆராய்ந்து சரிசெய்யலாம். அந்தப் படிகளை எழுதி வைப்பதுதான் பக் அறிக்கையின் மிகப் பயனுள்ள பகுதி.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"தீவிரம் (செவெரிட்டி)","text":"சிறு எரிச்சல் முதல் எல்லாமே நின்றுபோவது வரை, ஒரு பிரச்சினையின் விளைவு எவ்வளவு மோசம் என்பது.","also":["severity","severity level"]},{"id":"deploy","g":"change","word":"டெப்ளாய்","text":"மென்பொருளின் புதிய பதிப்பை, சோதனை நகல் அல்லது நேரலைச் சேவை போல, அதை இயக்கும் கணினிகளில் நகலெடுத்தல்."},{"id":"release","g":"change","word":"வெளியீடு","text":"ஒன்றாக லைவ் போகும், பெயரிடப்பட்ட முடிந்த வேலைகளின் தொகுப்பு; என்ன மாறியது என்ற சிறு குறிப்புகளுடன். 🚀 வெளியீடுகள் முடிந்த கார்டுகளிலிருந்து குறிப்புகளை எழுதும்.","also":["வெளியீடுகள்","ரிலீஸ்","release"]},{"id":"rollback","g":"change","word":"திரும்பப் பெறுதல்","text":"புதிய பதிப்பு சிக்கலை ஏற்படுத்தும்போது, வேலை செய்த கடைசிப் பதிப்புக்குத் திரும்புதல். AI-gile-இல், Roll back ஒவ்வொரு மாற்றத்திலும் எழுதப்பட்ட செயல்தவிர் படிகளை ஒரே சரிபார்ப்புப் பட்டியலாகத் திரட்டும்.","also":["rollback","ரோல்பேக்","திரும்பப் பெறு"]},{"id":"live","g":"change","word":"லைவ்","text":"சோதித்துப் பார்க்கும் நகலைப் போல் இல்லாமல், மக்கள் உண்மையில் பயன்படுத்தும் பதிப்பு. டெவலப்பர்கள் இதை புரொடக்ஷன் என்றும் சொல்வார்கள்.","also":["live","production","புரொடக்ஷன்"],"noTip":1},{"id":"change","g":"change","word":"மாற்றம்","text":"மக்கள் நம்பியிருக்கும் ஒன்றில் திட்டமிட்ட மாற்றம், முதலில் எழுதி வைக்கப்படும்: என்ன, ஏன், இடர், எப்போது, எப்படித் திரும்பப் பெறுவது. 🔀 மாற்றத்தைக் கோரு மூலம் தொடங்குங்கள்.","also":["மாற்றங்கள்","மாற்றக் கோரிக்கை","மாற்றக் கோரிக்கைகள்"],"noTip":1},{"id":"risk","g":"change","word":"இடர்","text":"தவறாகப் போகக்கூடிய ஒன்று; எவ்வளவு சாத்தியம், எவ்வளவு மோசம் என்பதைக் கொண்டு மதிப்பெண் இடப்படும். ⚠️ இடர்கள் அவற்றை ஒரே பட்டியலில் வைக்கும், அதிக மதிப்பெண் முதலில், ஒவ்வொன்றுக்கும் மீண்டும் பார்க்க ஒரு தேதியுடன்.","also":["இடர்கள்","ரிஸ்க்","இடர் பதிவேடு"]},{"id":"chgwin","g":"change","word":"மாற்ற நேர சாளரம்","text":"மாற்றங்கள் லைவ் போகலாம் என்ற நேரங்கள், உதாரணமாக அமைதியான செவ்வாய் மாலை. சாளரத்துக்கு வெளியே, அவசரம் இல்லாவிட்டால் ஒரு மாற்ற கார்டை முடிக்க முடியாது.","also":["மாற்ற நேர சாளரங்கள்","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"ஒரு மாற்றம் நேரலைக்குப் போவதற்கு முன் கடைசிச் சரிபார்ப்பு: ஒப்புதல் அளிக்க வேண்டிய ஒவ்வொருவரும் Go அல்லது No go என்பார்கள். எல்லோரும் Go என்றால் மட்டுமே அது தொடரும்.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"ஒப்புதல்","text":"வேலை தொடங்கும் முன் ஒரு சரிக்காகக் காத்திருப்பது. நண்பர் கொடுக்கும் கார்டு, அல்லது ஒரு மாற்றம், நீங்கள் ஒப்புதல் தரும் வரை அல்லது மறுக்கும் வரை ✅ ஒப்புதல்கள்-இல் காத்திருக்கும்.","also":["ஒப்புதல்கள்","அனுமதி"]},{"id":"quiettime","g":"change","word":"அமைதி நேரம்","text":"நேரலை ஒளிபரப்பு, டெமோ அல்லது இரவு நேரம் போல, எதுவும் நேரலைக்குப் போகாத ஒரு காலம். டீம்கள் தொடர்ந்து வேலை செய்து சோதிக்கும், ஆனால் நேரலைக்குப் போவது அது முடியும் வரை காத்திருக்கும். மற்ற இடங்களில் இதை change freeze என்பார்கள்.","also":["அமைதி நேரங்கள்","மாற்ற முடக்கம்","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"மென்பொருளைக் கட்டுபவர்களும் அதை இயக்குபவர்களும் ஒரே டீமாக, நிறைய தானியக்கத்துடன் வேலை செய்யும் முறை; அதனால் மாற்றங்கள் அடிக்கடி, பாதுகாப்பாக வெளியாகும்."},{"id":"cicd","g":"change","word":"CI/CD (தொடர் ஒருங்கிணைப்பும் தொடர் விநியோகமும்)","text":"எல்லோரின் மாற்றங்களும் அடிக்கடி முதன்மைப் பதிப்பில் இணைக்கப்பட்டு ஒவ்வொரு முறையும் தானாகச் சரிபார்க்கப்படும் (continuous integration); அதனால் மென்பொருள் எப்போதும் ஒரு பொத்தானை அழுத்தினால் வெளியாகத் தயாராக இருக்கும் (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"தொடர் வெளியீடு (கன்டினியூவஸ் டெப்ளாய்மென்ட்)","text":"தொடர் விநியோகத்தை விட ஒரு படி மேல்: சரிபார்ப்புகளில் தேறும் ஒவ்வொரு மாற்றமும், அழுத்த பொத்தான் எதுவும் இல்லாமல், தானாகவே வெளியாகும்.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"பைப்லைன்","text":"ஒரு மாற்றம் வெளியாகும் வழியில் கடந்து செல்லும் தானியங்கிப் படிகளின் தொடர்: கட்டுதல், சோதித்தல், பிறகு வெளியிடுதல்.","also":["pipeline","pipelines"]},{"id":"environment","g":"change","word":"சூழல் (என்விரான்மென்ட்)","text":"கட்டுவதற்கு ஒன்று, சோதிப்பதற்கு ஒன்று, நேரலை ஒன்று போல, ஒரு நோக்கத்துக்கான அமைப்பின் தனி நகல்.","also":["environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"மேம்பாட்டுச் சூழல்","text":"ஒரு டெவலப்பர் வேலை செய்யும் நகல், பெரும்பாலும் அவர் சொந்தக் கணினியில்; அங்கே எதையாவது உடைத்தாலும் யாருக்கும் பாதிப்பில்லை.","also":["development environment","dev environment"]},{"id":"testenv","g":"change","word":"சோதனைச் சூழல்","text":"உண்மையான சேவையைத் தொடாமல் இருக்க, சோதனைக்கு மட்டுமே பயன்படும் அமைப்பின் தனி நகல்.","also":["test environment","test environments"]},{"id":"staging","g":"change","word":"ஸ்டேஜிங்","text":"நேரலையைப் போலவே அமைக்கப்பட்ட கடைசி நகல்; ஒரு மாற்றம் நேரலைக்குப் போகும் முன் இறுதிச் சரிபார்ப்புக்காக.","also":["staging","staging environment"]},{"id":"artifact","g":"change","word":"பில்ட் ஆர்ட்டிஃபேக்ட் (பில்ட் உருவாக்கும் கோப்பு)","text":"சேமிக்க, சரிபார்க்க அல்லது நேரலைக்குக் கொண்டுவரத் தயாராக, ஒரு பில்ட் உருவாக்கும் கோப்பு அல்லது தொகுப்பு.","also":["build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"ஹாட்ஃபிக்ஸ் (அவசரத் திருத்தம்)","text":"முக்கியமான ஒன்று உடைந்துவிட்டதால், வழக்கமான திட்டத்துக்கு வெளியே, விரைவாக நேரலைக்குக் கொண்டுவரப்படும் அவசரத் திருத்தம்.","also":["hotfix","hotfixes"]},{"id":"patch","g":"change","word":"பேட்ச்","text":"ஒரு பக்கைச் சரிசெய்யும் அல்லது பாதுகாப்பு ஓட்டையை அடைக்கும் சிறு புதுப்பிப்பு. பாதுகாப்பு பேட்ச்களை விரைவாகப் பயன்படுத்துவது முக்கியம்.","also":["patch","patches","security patch","security patches"]},{"id":"version","g":"change","word":"பதிப்பு எண்","text":"உங்களிடம் எந்த வெளியீடு உள்ளது என்று சொல்லும் 2.4.1 போன்ற லேபிள். பெரும்பாலும் பெரிய மாற்றங்களுக்கு முதல் எண்ணும் சிறு திருத்தங்களுக்குக் கடைசி எண்ணும் மாறும்.","also":["பதிப்பு எண்கள்","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"வெளியீட்டுக் குறிப்புகள் (ரிலீஸ் நோட்ஸ்)","text":"ஒரு வெளியீட்டில் என்ன மாறியது என்பதன் சிறிய, எளிய பட்டியல், அதைப் பயன்படுத்துபவர்களுக்காக; திருத்தங்களும் தெரிந்த எல்லைகளும் உட்பட. சேஞ்ச்லாக் என்றும் சொல்வார்கள்.","also":["release notes","changelog","change log"]},{"id":"flag","g":"change","word":"ஃபீச்சர் ஃப்ளாக் (அம்சச் சுவிட்ச்)","text":"ஒரு அம்சத்துக்கான ஆன், ஆஃப் சுவிட்ச்; அதனால் புதிய வேலை மறைவாக வெளியாகி, புதிய வெளியீடு இல்லாமலேயே இயக்கப்படலாம் (அல்லது மீண்டும் அணைக்கப்படலாம்).","also":["feature flag","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"முன்னோக்கிச் சரிசெய்தல் (ரோல் ஃபார்வர்ட்)","text":"பழையதற்குத் திரும்பாமல், சரிசெய்யப்பட்ட புதிய பதிப்பை விரைவாக வெளியிட்டு, மோசமான வெளியீட்டைச் சரிசெய்தல்.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"கேனரி வெளியீடு","text":"ஒரு மாற்றத்தை முதலில் சிறு குழுவுக்கு மட்டும் வெளியிட்டு, சரியாகத் தெரிந்த பிறகே எல்லோருக்கும் வெளியிடுதல். சுரங்கத் தொழிலாளர்கள் முன்னெச்சரிக்கைக்காக நிலத்தடிக்கு எடுத்துச் சென்ற கேனரிப் பறவைகளின் பெயரால் அழைக்கப்படுகிறது.","also":["canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"ப்ளூ-க்ரீன் வெளியீடு","text":"நேரலை அமைப்பின் இரண்டு நகல்களை வைத்திருந்து, மக்களை ஒரே நேரத்தில் புதியதுக்கு மாற்றுதல்; தவறாகப் போனால் உடனே திரும்பிவிடலாம்.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"நிறுத்தமில்லா வெளியீடு","text":"பயனர்களுக்குச் சேவை ஒருபோதும் நிற்காமல், புதிய பதிப்பை நேரலைக்குக் கொண்டுவருதல்.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"மாற்றத்தை எளிதாக்குதல் (சேஞ்ச் என்னேபிள்மென்ட்)","text":"மாற்றங்கள் வெற்றி பெற உதவுதல்: அபாயத்தை எடைபோட்டு, சரியான ஒப்புதல் பெற்று, நல்ல நேரத்தைத் தேர்ந்தெடுத்தல். மாற்ற மேலாண்மை (change management) என்றும் சொல்வார்கள்.","also":["change enablement","change management","மாற்ற மேலாண்மை"]},{"id":"cab","g":"change","word":"மாற்ற ஆலோசனை வாரியம் (CAB)","text":"முக்கிய மாற்றங்களைப் பார்த்து, அவை நடக்கலாமா, எப்போது நடக்கலாம் என்று ஒப்புக்கொள்ளும் குழு.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"வழக்கமான மாற்றம் (ஸ்டாண்டர்ட் சேஞ்ச்)","text":"ஒவ்வொரு முறையும் அதே சோதிக்கப்பட்ட வழியில் செய்யப்படும் குறைந்த அபாய மாற்றம்; அதனால் முன்கூட்டியே ஒப்புதல் அளிக்கப்படும்.","also":["standard change","standard changes"]},{"id":"normchange","g":"change","word":"சாதாரண மாற்றம் (நார்மல் சேஞ்ச்)","text":"நடப்பதற்கு முன் சரிபார்க்கப்பட்டு ஒப்புதல் பெற வேண்டிய மாற்றம்.","also":["normal change","normal changes"]},{"id":"emergchange","g":"change","word":"அவசர மாற்றம்","text":"பெரிய சிக்கலைச் சரிசெய்ய அல்லது தடுக்க உடனே நடக்க வேண்டிய மாற்றம்; அதற்கேற்ற விரைவான ஒப்புதலுடன்.","also":["emergency change","emergency changes"]},{"id":"automation","g":"change","word":"தானியக்கம் (ஆட்டோமேஷன்)","text":"திரும்பத் திரும்ப வரும் வேலையைக் கணினியே செய்யவைத்தல்; அதனால் அது வேகமாகவும் ஒவ்வொரு முறையும் ஒரே மாதிரியும் நடக்கும்.","also":["தானியக்கம்","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"உள்கட்டமைப்பு","text":"மென்பொருள் ஓடுவதற்கான இயந்திரங்கள், நெட்வொர்க்குகள், சேவைகள்.","also":["infrastructure","infra"]},{"id":"iac","g":"change","word":"கோடாக உள்கட்டமைப்பு (IaC)","text":"உங்கள் சர்வர்களையும் அமைப்புகளையும் கோடுடன் சேர்த்து வைத்திருக்கும் கோப்புகளில் விவரித்தல்; அதனால் ஒவ்வொரு முறையும் அதே மாதிரியே மீண்டும் உருவாக்கலாம்.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"கிளவுட் (மேகம்)","text":"இயந்திரங்களைச் சொந்தமாக வைத்திருப்பதற்குப் பதிலாக, இணையம் வழியாக ஒரு பெரிய நிறுவனத்திடமிருந்து கணினிகள், சேமிப்பு, சேவைகளை வாடகைக்கு எடுத்தல்.","also":["மேகக் கணினி","cloud","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"கிளவுட் வழங்குநர்","text":"Amazon Web Services (AWS), Microsoft Azure அல்லது Google Cloud போல, இணையம் வழியாகக் கணினி வசதிகளை வாடகைக்கு விடும் நிறுவனம்.","also":["கிளவுட் வழங்குநர்கள்","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"ஹோஸ்டிங்","text":"மக்கள் அணுகும்படி உங்கள் ஆப் அல்லது இணையதளம் வசிக்கும், இயங்கும் இடம்; பொதுவாக ஒரு நிறுவனத்திடம் வாடகைக்கு எடுக்கப்படும்.","also":["hosting","இணைய ஹோஸ்டிங்"]},{"id":"domain","g":"change","word":"டொமைன் பெயர்","text":"example.com போல மக்கள் தட்டச்சு செய்யும் இணைய முகவரி. இதை ஆண்டுக்கு வாடகைக்கு எடுக்கிறீர்கள், எனவே புதுப்பிக்க வேண்டும்.","also":["டொமைன்","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"domain name system என்பதன் சுருக்கம்: example.com போன்ற பெயரைச் சரியான கணினியின் முகவரியாக மாற்றும், இணையத்தின் முகவரிப் புத்தகம்.","also":["domain name system"]},{"id":"container","g":"change","word":"கன்டெய்னர்","text":"ஒரு ஆப்பையும் அதற்குத் தேவையான எல்லாவற்றையும் கொண்ட மூடிய பொதி; அதனால் எந்தக் கணினியிலும் ஒரே மாதிரி ஓடும். Docker மிகவும் அறியப்பட்ட கருவி.","also":["கன்டெய்னர்கள்","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"மெய்நிகர் கணினி (VM)","text":"ஒரு உண்மையான கணினிக்குள் ஓடும் போலிக் கணினி; அதனால் ஒரு பெரிய இயந்திரம் பலவாகச் செயல்பட முடியும்.","also":["VM","VMs","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"சர்வர்லெஸ்","text":"எந்த சர்வரையும் நீங்களே கவனிக்காமல் கோடை ஓட்டுதல்: தேவைப்படும்போது வழங்குநர் அதை ஓட்டுவார், நீங்கள் பயன்படுத்தியதற்கு மட்டும் பணம் செலுத்துவீர்கள்."},{"id":"lb","g":"change","word":"லோடு பேலன்சர்","text":"எந்த ஒன்றும் திணறாமல் இருக்க, வருபவர்களைப் பல சர்வர்களுக்குப் பிரித்துவிடும் அமைப்பு.","also":["load balancer","load balancers"]},{"id":"cache","g":"change","word":"கேஷ்","text":"அதே விஷயத்தை மீண்டும் கொண்டுவரவோ கணக்கிடவோ வேண்டியதில்லாமல், சமீபத்திய முடிவுகளை அருகிலேயே வைத்திருக்கும் வசதியான சேமிப்பு. இதை அழித்தால் பழையதாகத் தெரியும் பக்கங்கள் சரியாகலாம்.","also":["cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"உள்ளடக்க விநியோக வலையமைப்பு (CDN)","text":"உங்கள் பக்கங்கள், படங்களின் நகல்களை உங்கள் பார்வையாளர்களுக்கு அருகில் வைத்திருக்கும் உலகளாவிய சர்வர்களின் தொகுப்பு; அதனால் அவை விரைவாக ஏற்றப்படும்.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"இடமாற்றம் (மைக்ரேஷன்)","text":"தரவையோ அமைப்புகளையோ பழைய ஏற்பாட்டிலிருந்து புதியதுக்கு மாற்றுதல், அல்லது தரவுத்தளம் எப்படி அமைந்திருக்கிறது என்பதை கவனமாக மாற்றுதல்.","also":["மைக்ரேஷன்","migration","migrations","database migration"]},{"id":"service","g":"run","word":"சேவை","text":"நீங்கள் உருவாக்கிய, மக்கள் நம்பியிருக்கும் ஒன்று, இணையதளம் அல்லது ஆப் போல; தொடர்ந்து இயங்க பராமரிக்கப்படும். “இந்தத் திட்டம் ஒரு சேவை” என்பதைத் டிக் செய்து, அது என்ன தருகிறது, யார் பயன்படுத்துகிறார்கள், யார் ஆன்-கால் என்று சொல்லுங்கள்.","also":["சேவைகள்","சர்வீஸ்","service"]},{"id":"uptimepct","g":"run","word":"இயங்கு நேரம் (அப்டைம்)","text":"ஒரு சேவை வேலை செய்யும் நேரத்தின் பங்கு, பொதுவாக சதவீதமாக. 99.9% என்றாலும் மாதத்துக்கு சுமார் 43 நிமிடம் செயலிழப்பு இருக்கலாம்.","also":["uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"அப்டைம் சோதனை","text":"சில நிமிடங்களுக்கு ஒருமுறை, உங்கள் சேவை இன்னும் பதில் தருகிறதா என்று பார்க்கும் தானியங்கி சோதனை. தொடர்ந்து பலமுறை தோல்வியடைந்தால், AI-gile தானாகவே ஒரு சம்பவ கார்டைத் திறக்கும்.","also":["uptime checks","இயங்கு நேரச் சரிபார்ப்புகள்"]},{"id":"statuspage","g":"run","word":"நிலைப் பக்கம்","text":"ஒரு சேவை இயங்குகிறதா (பச்சை, ஆரஞ்சு அல்லது சிவப்பு) என்பதைச் சமீபத்திய செய்தியுடன் காட்டும் பொதுப் பக்கம்; பயன்படுத்துபவர்கள் கேட்பதற்குப் பதிலாகத் தாங்களே பார்க்கலாம்.","also":["நிலைப் பக்கங்கள்","ஸ்டேட்டஸ் பக்கம்","status page"]},{"id":"desk","g":"run","word":"சேவை டெஸ்க்","text":"உங்கள் சேவையைப் பயன்படுத்துபவர்களிடமிருந்து கேள்விகளும் புகார்களும் வந்து சேரும் இடம். AI-gile ஒவ்வொன்றையும் கோரிக்கை, சம்பவம் அல்லது யோசனை என்று பிரிக்கிறது, ஏற்கெனவே சொல்லப்பட்ட ஒன்று போலத் தெரிந்தால் அதையும் சொல்கிறது.","also":["சேவை டெஸ்க்குகள்","ஹெல்ப் டெஸ்க்","உதவி மையம்","டெஸ்க்"]},{"id":"svcrequest","g":"run","word":"சேவைக் கோரிக்கை","text":"ஏதோ உடைந்திருக்கிறது என்று சொல்வதற்குப் பதில், புதிய கணக்கு அல்லது கொஞ்சம் உதவி போன்ற சாதாரணமான ஒன்றை ஒருவர் கேட்பது. இது தன் முறைக்காகக் காத்திருக்கும்; சம்பவம் முதலில் வரும்.","also":["சேவைக் கோரிக்கைகள்","கோரிக்கை","கோரிக்கைகள்"]},{"id":"incident","g":"run","word":"சம்பவம்","text":"இணையதளம் முடங்குவது அல்லது மிக மெதுவாவது போல, இப்போது அதைப் பயன்படுத்தும் மக்களுக்கு உடைந்த அல்லது சரியாக வேலை செய்யாத ஒன்று. 🔥 சம்பவக் கார்டு வரிசையைத் தாண்டும்: அதை மீண்டும் வேலை செய்ய வைப்பதே முதலில்.","also":["சம்பவங்கள்","இன்சிடென்ட்","incident"]},{"id":"major","g":"run","word":"பெரிய சம்பவம்","text":"ஒரு பெரிய சம்பவம்: பலர் பாதிக்கப்படுகிறார்கள், அல்லது பணம் அல்லது தரவு ஆபத்தில். ஒரு பொத்தான் எல்லாக் குழுக்களையும் அதில் ஈடுபடுத்தும் (ஸ்வார்ம்), ஆன்-கால் நபரை எழுப்பும், ஒவ்வொரு 30 நிமிடமும் ஒரு நிலைச் செய்தி கேட்கும்.","also":["பெரிய சம்பவங்கள்","major incident"]},{"id":"oncall","g":"run","word":"ஆன்-கால்","text":"ஏதாவது உடைந்தால், இரவிலும் கூட, பதில் தருபவராக இருப்பது. ஒவ்வொரு சேவைக்கும் ஒரு ஆன்-கால் குழு உறுப்பினர் இருப்பார்; அதன் சம்பவங்களுக்கு அவரே முதலில் எழுப்பப்படுவார்.","also":["on call","on-call","ஆன் கால்"]},{"id":"replyby","g":"run","word":"பதில் தரவேண்டிய நேரம்","text":"ஒரு கார்டு முதல் பதிலுக்காக எவ்வளவு நேரம் காத்திருக்கலாம், உதாரணமாக ஒரு சம்பவத்துக்கு ஒரு மணி நேரம். அதன் பிறகு அதற்கு ஒரு சிவப்புக் கடிகாரம் வரும், அதனால் எதுவும் அமைதியாக மறக்கப்படாது. பதில் இலக்கு என்றும் சொல்வார்கள்.","also":["பதில் தரவேண்டிய நேரங்கள்","பதில் இலக்கு"]},{"id":"postmortem","g":"run","word":"போஸ்ட்-மார்ட்டம்","text":"ஒரு சம்பவத்துக்குப் பிறகு சுருக்கமான திரும்பிப் பார்வை: என்ன நடந்தது, எது உதவியது, எதை மாற்ற வேண்டும்; யாரையும் குற்றம் சாட்டாமல். இது இல்லாமல் ஒரு சம்பவத்தை மூட முடியாது.","also":["post-mortem","postmortem","சம்பவத்துக்குப் பிந்தைய ஆய்வு"]},{"id":"problem","g":"run","word":"சிக்கல்","text":"ஒன்று அல்லது பல சம்பவங்களுக்குப் பின்னால் மறைந்திருக்கும் காரணம். ஒரு 🧩 சிக்கல் கார்டு திரும்பத் திரும்ப வரும் சம்பவங்களை ஒன்றாகச் சேர்க்கும், அதனால் காரணம் கண்டுபிடிக்கப்பட்டு நிரந்தரமாகச் சரிசெய்யப்படும்.","also":["சிக்கல்கள்","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"மூல காரணம்","text":"ஏதோ உடைந்ததற்கான உண்மையான காரணம், தவறாகப் போவதாக நீங்கள் பார்த்தது மட்டுமல்ல. மூல காரணத்தைச் சரிசெய்தால் சம்பவம் திரும்ப வருவது நின்றுவிடும்.","also":["மூல காரணங்கள்","root cause"]},{"id":"workaround","g":"run","word":"தற்காலிக வழி","text":"உண்மையான சரிசெய்தல் தயாராகும் வரை விஷயங்களை இயங்க வைக்கும் ஒரு வழி, சிக்கிக்கொண்டால் ஒன்றை மறுதொடக்கம் செய்வது போல. யாரும் மீண்டும் யோசிக்கத் தேவையில்லாமல் இருக்க, இது சிக்கல் கார்டில் எழுதப்படும்.","also":["தற்காலிக வழிகள்","workaround","வொர்க்அரவுண்ட்"]},{"id":"knownerror","g":"run","word":"தெரிந்த பிழை","text":"காரணம் புரிந்துவிட்ட ஆனால் இன்னும் சரிசெய்யப்படாத பிரச்சினை, பொதுவாக ஒரு மாற்று வழி எழுதப்பட்டிருக்கும். 🧩 தெரிந்த பிழைகள் அவற்றைப் பட்டியலிடும்; அதனால் எல்லோரும் மீண்டும் தோண்டாமல் மாற்று வழியைப் பயன்படுத்துவார்கள்.","also":["தெரிந்த பிழைகள்","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"தெரிந்த வகைச் சிக்கலைச் சரிசெய்யப் படிப்படியான வழிமுறைகள், ஒவ்வொரு முறையும் ஒரே மாதிரி, விரைவாகச் செய்ய. ஒரு பெரிய சம்பவத்துக்குப் பிறகு, நீங்கள் சரி சொல்ல குழு ஒன்றைப் பரிந்துரைக்கலாம்.","also":["runbooks","ரன்புக்","செயல்முறைக் கையேடு"]},{"id":"ci","g":"run","word":"கட்டமைப்பு உருப்படி","text":"உங்கள் சேவை சார்ந்திருக்கும் ஒரு விஷயம், உதாரணமாக ஒரு சர்வர், ஒரு டொமைன், ஒரு சான்றிதழ், ஒரு கீ அல்லது ஒரு சப்ளையர். 🗂️ கட்டமைப்பு உருப்படிகள் இவற்றைச் சேவை வாரியாகப் பட்டியலிடும், அதனால் ஒரு சம்பவம் எதைப் பாதிக்கிறது, எதைப் புதுப்பிக்க அல்லது பேக்கப் எடுக்க வேண்டும் என்று பார்க்கலாம்.","also":["கட்டமைப்பு உருப்படிகள்"]},{"id":"expiry","g":"run","word":"காலாவதி தேதி","text":"இணையதளத்தின் பாதுகாப்புச் சான்றிதழ் அல்லது அதன் இணைய முகவரி போல, புதுப்பிக்காவிட்டால் ஒன்று வேலை செய்வதை நிறுத்தும் தேதி. AI-gile இந்தத் தேதிகளைக் கவனித்து, ஒவ்வொன்றையும் புதுப்பிக்க 30 நாட்களுக்கு முன் ஒரு கார்டை உருவாக்கும்; அதனால் எதுவும் திடீரென நிற்காது.","also":["காலாவதி தேதிகள்","காலாவதி","காலாவதி கண்காணிப்பு"]},{"id":"backup","g":"run","word":"பேக்கப்","text":"முன்பு சேமித்த உங்கள் தரவின் நகல்; ஏதாவது தொலைந்தாலோ சேதமடைந்தாலோ நம்பலாம். AI-gile ஒவ்வொரு நாளும் உங்கள் போர்டுகளுக்கு ஒரு பேக்கப் எடுக்கும்.","also":["backup","பேக்கப்கள்","காப்பு நகல்"]},{"id":"restore","g":"run","word":"மீட்டெடுத்தல்","text":"ஒரு பேக்கப்பிலிருந்து தரவைத் திரும்பக் கொண்டுவருவது. மீட்டெடுக்க முடியும் என்று தெரிந்தால்தான் ஒரு பேக்கப் உண்மையில் பயனுள்ளது, அதனால் அவ்வப்போது முயன்று பார்ப்பது நல்லது.","also":["மீட்டெடு","ரீஸ்டோர்","restore"]},{"id":"svcreview","g":"run","word":"சேவை மதிப்பாய்வு","text":"ஒரு சேவையின் ஒரு மாதத்தைத் திரும்பிப் பார்ப்பது: திறக்கப்பட்ட, சரிசெய்யப்பட்ட சம்பவங்கள், மக்களுக்கு எவ்வளவு விரைவில் பதில் கிடைத்தது, அப்டைம், பயன்படுத்திய டோக்கன்கள். மாதாந்திர மதிப்பாய்வு இதை ஒவ்வொரு சேவைக்கும் காட்டும்.","also":["சேவை மதிப்பாய்வுகள்","மாதாந்திர மதிப்பாய்வு","மாதாந்திர மதிப்பாய்வுகள்"]},{"id":"accessreview","g":"run","word":"அணுகல் மதிப்பாய்வு","text":"ஒவ்வொரு 90 நாட்களுக்கும் இன்னும் யார் உள்ளே வர முடியும் என்று சரிபார்த்தல்: பகிர்வு இணைப்புகள், நண்பர்களின் பங்குகள், சேமித்த கடவுச்சொற்கள், சாவிகள். ஒவ்வொன்றையும் வைத்துக்கொள்கிறீர்கள் அல்லது நீக்குகிறீர்கள்; அதனால் பழைய அணுகல் தங்கிவிடாது.","also":["அணுகல் மதிப்பாய்வுகள்"]},{"id":"improvements","g":"run","word":"மேம்பாட்டுப் பட்டியல்","text":"டீம் மேம்படுத்த முடிவு செய்த அனைத்தும் ஒரே இடத்தில்: ரெட்ரோ பரிந்துரைகள், மதிப்பாய்வு நடவடிக்கைகள், சிக்கல் சரிசெய்தல்கள், ஒவ்வொன்றும் அதன் நிலையுடன். 📈 மேம்பாடுகள் என்பதில் காணலாம்.","also":["மேம்பாட்டுப் பட்டியல்கள்","மேம்பாடுகள்"]},{"id":"tokencap","g":"run","word":"டோக்கன் வரம்பு","text":"ஒரு சேவையின் ஏஜென்ட்கள் பயன்படுத்தக்கூடிய டோக்கன்களுக்கான மாதாந்திர வரம்பு. 80%-இல் உங்களுக்கு எச்சரிக்கை வரும்; 100%-இல் அவர்களின் பின்னணி வேலை அடுத்த மாதம் வரை அல்லது நீங்கள் வரம்பை உயர்த்தும் வரை காத்திருக்கும்.","also":["டோக்கன் வரம்புகள்"]},{"id":"svcmgmt","g":"run","word":"சேவை மேலாண்மை","text":"ஒரு சேவையை அதைச் சார்ந்திருக்கும் மக்களுக்கு நாளுக்கு நாள் பயனுள்ளதாகவும் வேலை செய்வதாகவும் வைத்திருக்கத் தேவையான எல்லாம்.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"சம்பவங்கள், பிரச்சினைகள், மாற்றங்கள் போன்றவற்றை உள்ளடக்கிய, நல்ல சேவை மேலாண்மைக்கான பரவலாகப் பயன்படும் வழிகாட்டி. இந்தப் பெயர் முன்பு IT Infrastructure Library என்பதைக் குறித்தது."},{"id":"itsm","g":"run","word":"தகவல் தொழில்நுட்ப சேவை மேலாண்மை (ITSM)","text":"கோரிக்கைகள், சம்பவங்கள், மாற்றங்கள், மேம்பாடுகளைக் கையாளத் தெளிவான வழிகளுடன், தொழில்நுட்பத்தை மக்களுக்கான சேவையாக நடத்துதல்.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"நிர்வகிக்கப்படும் சேவை (மேனேஜ்டு சர்வீஸ்)","text":"அது எவ்வளவு நன்றாக வேலை செய்ய வேண்டும் என்ற ஒப்பந்தத்தின்கீழ், வேறொருவர் உங்களுக்காக இயக்கிப் பராமரிக்கும் சேவை.","also":["managed service","managed services"]},{"id":"svcowner","g":"run","word":"சேவை உரிமையாளர்","text":"ஒரு சேவை முழுவதற்கும் பொறுப்பேற்பவர்: அது எவ்வளவு நன்றாக வேலை செய்கிறது, எவ்வளவு செலவாகிறது, எப்படி மேம்படுகிறது.","also":["சேவை உரிமையாளர்கள்","service owner","service owners"]},{"id":"sla","g":"run","word":"சேவை நிலை ஒப்பந்தம் (SLA)","text":"ஒரு சேவை எவ்வளவு நன்றாக வேலை செய்யும் என்று வாடிக்கையாளர்களுக்கு எழுத்தில் தரும் வாக்குறுதி, “99.9% நேரம் இயங்கும்” அல்லது “ஒரு மணி நேரத்துக்குள் பதில்” போல; மீறினால் பெரும்பாலும் பணம் திரும்பக் கிடைக்கும்.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"சேவை நிலை இலக்கு (SLO)","text":"ஒரு காலத்தில் சேவை எவ்வளவு நன்றாக வேலை செய்ய வேண்டும் என்பதற்கான டீமின் சொந்த இலக்கு; பாதுகாப்புக்காக பொதுவாக SLA-வை விடச் சற்றுக் கடுமையாக வைக்கப்படும்.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"சேவை நிலை குறிகாட்டி (SLI)","text":"நன்றாக ஏற்றப்பட்ட வருகைகளின் பங்கு போல, இலக்குடன் ஒப்பிட்டுப் பார்க்கும் உண்மையான அளவீடு.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"கிடைக்கும் தன்மை","text":"மக்களுக்குத் தேவைப்படும்போது ஒரு சேவையைப் பயன்படுத்த முடிகிறதா என்பது; பெரும்பாலும் அப்டைமாக அளக்கப்படும்.","also":["availability","high availability"]},{"id":"downtime","g":"run","word":"செயலிழப்பு நேரம் (டவுன்டைம்)","text":"திட்டமிட்டதோ இல்லையோ, ஒரு சேவை வேலை செய்யாமல் அல்லது நிறுத்தப்பட்டிருக்கும் நேரம்.","also":["downtime","down time"]},{"id":"errorbudget","g":"run","word":"எரர் பட்ஜெட் (பிழை ஒதுக்கீடு)","text":"உங்கள் நம்பகத்தன்மை இலக்கு அனுமதிக்கும் சிறிய அளவு தோல்வி. கொஞ்சம் மீதமிருக்கும் வரை மாற்றங்களில் ரிஸ்க் எடுக்கலாம்; தீர்ந்துவிட்டால் வேகத்தைக் குறைப்பீர்கள்.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"சேவைத் தடை (அவுட்டேஜ்)","text":"பயனர்களுக்கு ஒரு சேவை முடங்கிப்போன அல்லது மோசமாக உடைந்த நேரம்.","also":["outage","outages"]},{"id":"degraded","g":"run","word":"தரம் குறைந்த நிலை","text":"வேலை செய்கிறது, ஆனால் மோசமாக: மெதுவாக, அல்லது சில பகுதிகள் வேலை செய்யாமல்.","also":["degraded","degraded service"]},{"id":"monitoring","g":"run","word":"கண்காணிப்பு (மானிட்டரிங்)","text":"பயனர்கள் கவனிப்பதற்கு முன்பே, முடிந்தால், பிரச்சினைகள் கண்டறியப்பட, ஒரு சேவையை எப்போதும் தானாகக் கவனித்தல்.","also":["monitoring"]},{"id":"observability","g":"run","word":"உள்நோக்கு திறன் (அப்சர்வபிலிட்டி)","text":"ஓர் அமைப்பின் பதிவுகள், எண்கள், தடங்களைக் கொண்டு, வெளியிலிருந்தே உள்ளே என்ன நடக்கிறது என்று எவ்வளவு நன்றாகச் சொல்ல முடியும் என்பது.","also":["observability","o11y"]},{"id":"log","g":"run","word":"பதிவு (லாக்)","text":"ஒரு புரோகிராம் தான் என்ன செய்கிறது என்று வைத்திருக்கும் தொடர் நாட்குறிப்பு; என்ன தவறு நடந்தது என்று கண்டுபிடிக்கப் பயன்படும்.","also":["லாக்","log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"ட்ரேஸ் (தடம்)","text":"ஒரு கோரிக்கை அமைப்பின் வெவ்வேறு பகுதிகள் வழியாகப் படிப்படியாக எப்படிப் பயணிக்கிறது என்பதன் பதிவு; எங்கே மெதுவானது என்று காட்டும்.","also":["trace","traces","tracing"]},{"id":"latency","g":"run","word":"தாமதம் (லேட்டன்சி)","text":"கிளிக் செய்ததற்கும் பக்கம் தோன்றுவதற்கும் இடையிலான காத்திருப்பு போல, ஒன்று பதிலளிக்க எவ்வளவு நேரம் எடுக்கிறது என்பது.","also":["latency"]},{"id":"alert","g":"run","word":"எச்சரிக்கை (அலர்ட்)","text":"இணையதளம் பதிலளிக்காதது போல, ஏதோ ஒன்றுக்குக் கவனம் தேவை என்று சொல்லும் தானியங்கிச் செய்தி.","also":["எச்சரிக்கைகள்","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"எச்சரிக்கைச் சோர்வு","text":"எச்சரிக்கைகள் மிக அதிகமாக இருந்து, முக்கியமானவை உட்பட மக்கள் அவற்றைப் புறக்கணிக்கத் தொடங்கும் நிலை.","also":["alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"டாஷ்போர்டு","text":"மிக முக்கியமான எண்களையும் நிலைகளையும் ஒரே பார்வையில் காட்டும் திரை.","also":["டாஷ்போர்டுகள்","dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"பேஜிங் (அவசர அழைப்பு)","text":"ஒரு பிரச்சினை பற்றி, பணியில் இருக்கும் நபரை அவசரமாக அழைத்தல் அல்லது எழுப்புதல்.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"மேல்நிலைக்குக் கொண்டுசெல்லுதல் (எஸ்கலேஷன்)","text":"தற்போதைய நிலையில் அல்லது போதுமான வேகத்தில் ஒரு பிரச்சினையைத் தீர்க்க முடியாதபோது, அதிகத் திறமையோ அதிகாரமோ உள்ளவரை அழைத்து வருதல்.","also":["escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"ட்ரையேஜ் (முன்னுரிமை வகைப்பாடு)","text":"மிக மோசமானது முதலில் கையாளப்பட, வரும் பிரச்சினைகளை எவ்வளவு அவசரம், எவ்வளவு முக்கியம் என்று விரைவாகப் பிரித்தல்.","also":["triage","triaged"]},{"id":"impact","g":"run","word":"தாக்கம்","text":"ஒன்று மக்களை எவ்வளவு பாதிக்கிறது: எத்தனை பேர், எவ்வளவு மோசமாக.","noTip":1},{"id":"urgency","g":"run","word":"அவசரம்","text":"ஒன்றை எவ்வளவு விரைவாகக் கையாள வேண்டும் என்பது. தாக்கமும் அவசரமும் சேர்ந்து முன்னுரிமையை நிர்ணயிக்கின்றன.","noTip":1},{"id":"plevels","g":"run","word":"முன்னுரிமை நிலைகள் (P1, P2…)","text":"ஒரு பிரச்சினை எவ்வளவு அவசரம் என்பதற்கான லேபிள்கள். P1 மிகத் தீவிரமானது, உடனே நடவடிக்கை தேவை.","also":["P1","P2","P3","P4","priority levels"]},{"id":"queue","g":"run","word":"டிக்கெட் வரிசை","text":"எடுத்துக்கொள்ளக் காத்திருக்கும் கோரிக்கைகள், சம்பவங்களின் பட்டியல்.","also":["டிக்கெட் வரிசைகள்","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"முதல் நிலை, இரண்டாம் நிலை ஆதரவு","text":"ஆதரவின் நிலைகள்: முதல் நிலை அழைப்பை எடுத்து எளிய விஷயங்களைச் சரிசெய்யும்; இரண்டாம் நிலைக்குக் கடினமானவற்றுக்கான ஆழ்ந்த திறமைகள் உண்டு. Tier 1, Tier 2 என்றும் சொல்வார்கள்.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"சம்பவத் தலைவர் (இன்சிடென்ட் கமாண்டர்)","text":"ஒரு சம்பவத்துக்கான பதில் நடவடிக்கையை வழிநடத்தும் ஒரே நபர்; அதனால் யார் முடிவு செய்கிறார், யார் என்ன செய்கிறார் என்று எல்லோருக்கும் தெரியும்.","also":["incident commander","incident commanders","சம்பவத் தலைவர்கள்"]},{"id":"responsetime","g":"run","word":"பதில் நேரம்","text":"ஒரு கோரிக்கை அல்லது சம்பவத்தை யாராவது முதலில் எடுத்துக்கொள்வதற்கு முன் ஆகும் நேரம்.","also":["response time","response times"]},{"id":"resolution","g":"run","word":"தீர்வு நேரம்","text":"ஒரு கோரிக்கை அல்லது சம்பவம் புகாரளிக்கப்பட்டதிலிருந்து சரிசெய்யப்படும் வரை, முழுமையாகத் தீர்க்க ஆகும் நேரம்.","also":["resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"சராசரி மீட்பு நேரம் (MTTR)","text":"ஒரு சேவை உடைந்த பிறகு மீண்டும் வேலை செய்ய, சராசரியாக எவ்வளவு நேரம் ஆகிறது. MTTR சற்று வேறுபட்ட பொருள்களில் வரலாம், எனவே எதை அளக்கிறீர்கள் என்று சொல்லுங்கள்.","also":["MTTR","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"தோல்விகளுக்கிடையிலான சராசரி நேரம் (MTBF)","text":"ஏதாவது உடைவதற்கு முன் ஒரு சேவை சராசரியாக எவ்வளவு நேரம் ஓடுகிறது.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"உள்ளமைவு மேலாண்மைத் தரவுத்தளம் (CMDB)","text":"உங்கள் எல்லா உள்ளமைவு உருப்படிகளும், அவை எப்படி இணைகின்றன என்பதும் அடங்கிய பட்டியல்; எது எதைச் சார்ந்தது என்று பார்க்கலாம்.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"சொத்து (அசெட்)","text":"மடிக்கணினி, மென்பொருள் உரிமம் அல்லது டொமைன் போல, சேவையை நடத்த நீங்கள் வைத்திருக்கும் அல்லது பணம் செலுத்தும் மதிப்புள்ள எதுவும்.","also":["சொத்துகள்","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"திறன் திட்டமிடல் (கெபாசிட்டி பிளானிங்)","text":"வரப்போவதற்குப் போதுமான கணினி ஆற்றல், சேமிப்பு, ஆட்கள் இருப்பதை உறுதி செய்தல்.","also":["capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"அளவை விரிவாக்குதல் (ஸ்கேலிங்)","text":"ஓர் இயந்திரத்துக்கு அதிக ஆற்றல் கொடுத்தோ (scaling up) மேலும் இயந்திரங்களைச் சேர்த்தோ (scaling out) அதிகப் பயனர்களைச் சமாளித்தல்.","also":["scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"வணிகத் தொடர்ச்சி","text":"அலுவலகம், முக்கிய சப்ளையர் அல்லது கணினிகளை இழப்பது போல பெரிய தவறு நடக்கும்போது முக்கியமானவற்றைத் தொடர்ந்து நடத்துவதற்கான திட்டங்கள்.","also":["business continuity","business continuity plan","வணிகத் தொடர்ச்சித் திட்டம்"]},{"id":"dr","g":"run","word":"பேரிடர் மீட்பு (DR)","text":"ஒரு முழு டேட்டா சென்டரை இழப்பது போன்ற தீவிரமான ஒன்றுக்குப் பிறகு சேவையை மீட்கும் திட்டமும் கருவிகளும்.","also":["DR","disaster recovery"]},{"id":"rto","g":"run","word":"மீட்பு நேர இலக்கு (RTO)","text":"பேரிடருக்குப் பிறகு ஒரு சேவை மீண்டும் வேலை செய்யத் தொடங்குவதற்குள் அது செயலிழந்து இருக்கக்கூடிய அதிகபட்ச நேரம்.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"மீட்புப் புள்ளி இலக்கு (RPO)","text":"நேரத்தால் அளக்கப்படும், சமீபத்திய தரவில் எவ்வளவை இழக்கத் தயார் என்பது. ஒரு மணி நேர RPO என்றால் குறைந்தது ஒவ்வொரு மணிக்கும் காப்புப் பிரதி.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"மிகைக் காப்பு (ரிடண்டன்சி)","text":"இரண்டாவது சர்வர் போல உதிரிகளைத் தயாராக வைத்திருத்தல்; அதனால் ஒரு செயலிழப்பு சேவையை நிறுத்தாது.","also":["redundancy"]},{"id":"failover","g":"run","word":"ஃபெயில்ஓவர் (மாற்று இயக்கம்)","text":"வழக்கமான அமைப்பு செயலிழக்கும்போது தானாகவே உதிரி அமைப்புக்கு மாறுதல்.","also":["failover","fail over"]},{"id":"spof","g":"run","word":"ஒற்றைத் தோல்விப் புள்ளி","text":"உதிரி இல்லாததால், உடையும்போது எல்லாவற்றையும் தன்னுடன் வீழ்த்தும் ஒரு பகுதி.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"பராமரிப்பு நேரம்","text":"பராமரிப்புக்காக ஒரு சேவை நிறுத்தப்படக்கூடிய அல்லது மெதுவாக இருக்கக்கூடிய, பயனர்களுக்கு முன்கூட்டியே அறிவிக்கப்படும் திட்டமிட்ட நேரம்.","also":["maintenance window","maintenance windows","planned maintenance","திட்டமிட்ட பராமரிப்பு"]},{"id":"handover","g":"run","word":"ஒப்படைப்பு","text":"எதுவும் விடுபடாதபடி வேலை, அறிவு, பொறுப்பை இன்னொரு நபருக்கோ டீமுக்கோ கொடுத்தல்.","also":["handover","handovers"]},{"id":"kb","g":"run","word":"அறிவுத் தளம் (நாலெட்ஜ் பேஸ்)","text":"பயனர்களுக்கும் டீமுக்கும் உதவும் கட்டுரைகள், பதில்களின் தொகுப்பு.","also":["knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"வாடிக்கையாளர் திருப்தி (CSAT)","text":"பயனர்கள் எவ்வளவு மகிழ்ச்சியாக இருந்தார்கள் என்று சொல்லும் மதிப்பெண்; ஒரு கோரிக்கை மூடப்பட்ட பிறகு பெரும்பாலும் கேட்கப்படும்.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"சப்ளையர் (வழங்குநர்)","text":"உங்கள் ஹோஸ்டிங் வழங்குநர் போல, நீங்கள் சார்ந்திருக்கும் வெளி நிறுவனம். வெண்டர் அல்லது மூன்றாம் தரப்பு என்றும் சொல்வார்கள்.","also":["சப்ளையர்கள்","supplier","suppliers","vendor","vendors","third party","மூன்றாம் தரப்பு"],"noTip":1},{"id":"retire","g":"run","word":"சேவையை ஓய்வுபெறச் செய்தல்","text":"ஒரு சேவையைப் பாதுகாப்பாக நிரந்தரமாக நிறுத்துதல்: அதன் பயனர்களுக்குச் சொல்லி, அதன் தரவையும் அணுகலையும் கையாண்டு, அதன் செலவுகளை நிறுத்துதல்.","also":["service retirement","retiring a service"]},{"id":"eol","g":"run","word":"ஆயுள் முடிவு (EOL)","text":"ஒரு தயாரிப்பு, அதை உருவாக்கியவரிடமிருந்து புதுப்பிப்புகளோ ஆதரவோ பெறுவது நின்றுபோகும் நிலை; அதனால் அதை மாற்ற வேண்டும்.","also":["EOL","end of life","end-of-life"]},{"id":"cybersec","g":"sec","word":"இணையப் பாதுகாப்பு (சைபர் செக்யூரிட்டி)","text":"அமைப்புகளும் தரவும் உடைத்து நுழையப்படாமல், திருடப்படாமல், சேதமடையாமல் பாதுகாத்தல்.","also":["இணையப் பாதுகாப்பு","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"அடையாளச் சரிபார்ப்பு (ஆத்தென்டிகேஷன்)","text":"பொதுவாக கடவுச்சொல் அல்லது குறியீட்டால், ஒருவர் யார் என்று சரிபார்த்தல். பெரும்பாலும் authn என்று சுருக்கப்படும்.","also":["authentication","authn"]},{"id":"authz","g":"sec","word":"அனுமதி வழங்கல் (ஆதரைசேஷன்)","text":"ஒருவர் யார் என்று தெரிந்த பிறகு, அவர் என்ன செய்ய அனுமதிக்கப்படுகிறார் என்று சரிபார்த்தல். பெரும்பாலும் authz என்று சுருக்கப்படும்.","also":["authorisation","authorization","authz"]},{"id":"mfa","g":"sec","word":"பல-காரணி அங்கீகாரம் (MFA)","text":"கடவுச்சொல்லுடன் உங்கள் போனில் வரும் குறியீடு போல, இரண்டு அல்லது அதற்கு மேற்பட்ட சான்றுகளுடன் உள்நுழைதல். இரு-காரணி (2FA) என்றும் சொல்வார்கள்.","also":["MFA","2FA","two-factor","two-factor authentication","multi-factor authentication"]},{"id":"sso","g":"sec","word":"ஒற்றை உள்நுழைவு (SSO)","text":"உங்கள் வேலைக் கணக்கை எங்கும் பயன்படுத்துவது போல, ஒருமுறை உள்நுழைந்து பல அமைப்புகளுக்குள் செல்லுதல்.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"கடவுச்சொல் மேலாளர்","text":"வலுவான கடவுச்சொற்களை உருவாக்கி, உங்களுக்காக நினைவில் வைத்திருக்கும் ஆப்.","also":["கடவுச்சொல் மேலாளர்கள்","password manager","password managers"]},{"id":"secret","g":"sec","word":"ரகசியம் (சீக்ரெட்)","text":"ஒரு புரோகிராம் எதற்குள்ளாவது நுழையப் பயன்படுத்தும் கடவுச்சொல், சாவி அல்லது பிற தனிப்பட்ட குறியீடு. இதைப் பகிரவே கூடாது, கோடில் எழுதவும் கூடாது.","also":["ரகசியங்கள்","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API சாவி","text":"ஒரு புரோகிராம் வேறு சேவையின் API-ஐப் பயன்படுத்த அனுமதிக்கும், யார் பயன்படுத்துகிறார் (பணமும் செலுத்துகிறார்) என்பதைக் காட்டும் ரகசியக் குறியீடு.","also":["API சாவிகள்","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"அணுகல் டோக்கன்","text":"ஒவ்வொரு முறையும் உங்கள் கடவுச்சொல் தேவைப்படாமல், புரோகிராமுக்கு உள்ளே வர அனுமதி உண்டு என்று நிரூபிக்கும் தற்காலிக அனுமதிச்சீட்டு. AI டோக்கனும் இதுவும் ஒன்றல்ல.","also":["access token","access tokens"]},{"id":"encryption","g":"sec","word":"குறியாக்கம் (என்கிரிப்ஷன்)","text":"சரியான சாவி உள்ளவர் மட்டுமே படிக்க முடியும்படி, தகவலை மற்றவர்களுக்குப் புரியாத வடிவத்துக்கு மாற்றுதல்.","also":["என்கிரிப்ஷன்","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"வலைப்பக்கங்கள் பயணிக்கும் பாதுகாப்பான வழி, உங்கள் உலாவியில் பூட்டுச் சின்னமாகத் தெரியும்; இடையில் யாரும் அவற்றைப் படிக்கவோ மாற்றவோ முடியாது."},{"id":"cert","g":"sec","word":"SSL/TLS சான்றிதழ்","text":"ஓர் இணையதளம் தான் யார் என்று நிரூபித்து HTTPS-ஐப் பயன்படுத்த உதவும் டிஜிட்டல் அடையாள அட்டை. இது காலாவதியாகும், எனவே புதுப்பிக்க வேண்டும்.","also":["சான்றிதழ்","சான்றிதழ்கள்","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"அனுமதிகள்","text":"யார் எதைப் பார்க்கலாம் அல்லது மாற்றலாம் என்பதற்கான விதிகள்.","also":["permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"குறைந்தபட்ச உரிமை (லீஸ்ட் ப்ரிவிலெஜ்)","text":"ஒவ்வொரு நபருக்கும் புரோகிராமுக்கும் அவர்களுக்கு உண்மையில் தேவையான அணுகலை மட்டும், தேவைப்படும் நேரத்துக்கு மட்டும் கொடுத்தல்.","also":["least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"பங்கு அடிப்படையிலான அணுகல் கட்டுப்பாடு (RBAC)","text":"ஒவ்வொருவருக்கும் தனித்தனியாக அல்லாமல், பார்வையாளர் அல்லது திருத்துபவர் போன்ற பங்கு மூலம் அணுகல் கொடுத்தல்.","also":["RBAC","role-based access","role-based access control"]},{"id":"vuln","g":"sec","word":"பாதுகாப்பு ஓட்டை (வல்னரபிலிட்டி)","text":"யாராவது உடைத்து நுழைய அல்லது தீங்கு செய்யப் பயன்படுத்தக்கூடிய பலவீனம்.","also":["பாதுகாப்பு ஓட்டைகள்","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"ஜீரோ-டே","text":"தயாரிப்பாளர்கள் சரிசெய்ய எந்த நேரமும் கிடைப்பதற்கு முன்பே தாக்குபவர்களுக்குத் தெரிந்திருக்கும் பலவீனம்.","also":["zero-day","zero-days","zero day"]},{"id":"malware","g":"sec","word":"தீம்பொருள் (மால்வேர்)","text":"சேதப்படுத்த, உளவு பார்க்க அல்லது திருடுவதற்காக உருவாக்கப்பட்ட, வைரஸ்கள் போன்ற தீங்கான மென்பொருள்.","also":["மால்வேர்","malware"]},{"id":"ransomware","g":"sec","word":"ரான்சம்வேர் (மீட்புத்தொகை மால்வேர்)","text":"உங்கள் கோப்புகளைப் பூட்டி, திறக்கப் பணம் கேட்கும் மால்வேர். நல்ல காப்புப் பிரதிகளே சிறந்த தற்காப்பு.","also":["ரான்சம்வேர்","ransomware","ransomware attack"]},{"id":"phishing","g":"sec","word":"ஃபிஷிங் (ஏமாற்று மோசடி)","text":"கடவுச்சொற்களையோ பணத்தையோ கொடுக்க வைக்க, அல்லது தீங்கான ஒன்றைத் திறக்க வைக்க உங்களை ஏமாற்ற முயலும் போலிச் செய்திகள்.","also":["ஃபிஷிங்","phishing","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"சமூகப் பொறியியல் (சோஷியல் இன்ஜினியரிங்)","text":"“IT ஆதரவு” என்று வரும் போலி அழைப்பு போல, கணினிகளை அல்ல, மனிதர்களை ஏமாற்றி அணுகலைப் பெறுதல்."},{"id":"firewall","g":"sec","word":"ஃபயர்வால்","text":"எந்த நெட்வொர்க் போக்குவரத்து உள்ளே வரலாம், வெளியே போகலாம் என்று முடிவு செய்யும் காவலர்.","also":["firewall","firewalls","தீச்சுவர்"]},{"id":"vpn","g":"sec","word":"VPN","text":"virtual private network என்பதன் சுருக்கம்: இணையம் வழியாகச் செல்லும் தனிப்பட்ட, குறியாக்கப்பட்ட இணைப்பு; பணியிட அமைப்புகளைப் பாதுகாப்பாக அடைய இது பெரும்பாலும் பயன்படும்.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"சேவை மறுப்புத் தாக்குதல் (DoS, DDoS)","text":"உண்மையான மக்கள் பயன்படுத்த முடியாத அளவுக்கு ஒரு சேவையைப் போலியான போக்குவரத்தால் மூழ்கடித்தல். DDoS என்றால் அது ஒரே நேரத்தில் பல கணினிகளிலிருந்து வருகிறது.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"ஊடுருவல் சோதனை (பென் டெஸ்ட்)","text":"உண்மையான தாக்குபவர்கள் கண்டுபிடிக்கும் முன் பலவீனங்கள் கண்டறியப்பட, நட்பான நிபுணர்களை உடைத்து நுழைய முயற்சிக்க வைத்தல்.","also":["pen test","pen testing","penetration test","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"பாதுகாப்புத் தணிக்கை","text":"நல்ல நடைமுறைகளின் பட்டியலை வைத்து, ஒன்று எவ்வளவு நன்றாகப் பாதுகாக்கப்பட்டுள்ளது என்று கவனமாகச் சரிபார்த்தல்.","also":["பாதுகாப்புத் தணிக்கைகள்","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"அச்சுறுத்தல் மாதிரியாக்கம்","text":"ஒன்றை யார் தாக்கக்கூடும், எப்படி, அவர்களைத் தடுக்க நீங்கள் என்ன செய்வீர்கள் என்று சிந்தித்தல்.","also":["threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"தரவு கசிவு (டேட்டா ப்ரீச்)","text":"தனிப்பட்ட தகவல் அது இருக்கக் கூடாதவர்களிடம் போவது, அல்லது அனுமதியின்றி இழக்கப்படுவது, மாற்றப்படுவது.","also":["தரவு கசிவு","data breach","data breaches"]},{"id":"pii","g":"sec","word":"தனிப்பட்ட தரவு","text":"பெயர், மின்னஞ்சல் முகவரி அல்லது இருப்பிடம் போல, அடையாளம் காணக்கூடிய ஒருவரைப் பற்றிய எந்தத் தகவலும். PII என்றும் சொல்வார்கள்.","also":["தனிப்பட்ட தகவல்","personal data","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"தனிப்பட்ட தரவு பற்றிய ஐரோப்பியச் சட்டம் (இங்கிலாந்துக்கு அதன் சொந்தப் பதிப்பு உண்டு): தேவையானதை மட்டும் சேகரியுங்கள், பாதுகாப்பாக வையுங்கள், மக்கள் தங்கள் தரவைப் பார்க்கவும் அழிக்கவும் அனுமதியுங்கள்.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"தரவுப் பாதுகாப்பு","text":"தனிப்பட்ட தரவை முறையாகவும் சட்டத்துக்கு உட்பட்டும் கவனித்துக்கொள்ளுதல்.","also":["data protection","data protection law","தரவுப் பாதுகாப்புச் சட்டம்"]},{"id":"privacypolicy","g":"sec","word":"தனியுரிமைக் கொள்கை","text":"என்ன தனிப்பட்ட தரவைச் சேகரிக்கிறீர்கள், ஏன், அதை என்ன செய்கிறீர்கள் என்பதைச் சொல்லும் பொதுப் பக்கம்.","also":["privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"சம்மதம் (கன்சென்ட்)","text":"தன் தரவு ஒரு குறிப்பிட்ட விதத்தில் பயன்படுத்தப்படுவதற்கு ஒருவர் தெளிவாக, சுதந்திரமாகச் சொல்லும் “சரி”. அவர் எப்போது வேண்டுமானாலும் அதைத் திரும்பப் பெறலாம்.","also":["consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"குக்கீ","text":"உள்நுழைந்திருப்பது போன்றவற்றை நினைவில் வைக்க, இணையதளம் உங்கள் உலாவியில் சேமிக்கும் சிறு கோப்பு. சிலவற்றுக்கு முதலில் உங்கள் சம்மதம் தேவை.","also":["குக்கீகள்","cookie","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"தரவைக் குறைத்துச் சேகரித்தல்","text":"அந்த வேலைக்கு உண்மையிலேயே தேவையான தனிப்பட்ட தரவை மட்டுமே சேகரித்து வைத்திருத்தல்.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"தரவு தக்கவைப்பு","text":"தரவு அழிக்கப்படுவதற்கு முன் எவ்வளவு காலம் வைக்கப்படுகிறது. தேவைக்கு மேல் வைக்காமல் இருப்பது பாதுகாப்பானது, பெரும்பாலும் சட்டமும் அதுவே.","also":["data retention","retention period"]},{"id":"anon","g":"sec","word":"அடையாள நீக்கம் (அனோனிமைசேஷன்)","text":"அதிலிருந்து இனி யாரையும் நியாயமாக அடையாளம் காண முடியாதபடி தரவை மாற்றுதல்.","also":["anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"புனைபெயராக்கம் (சூடோனிமைசேஷன்)","text":"பெயர்களையும் பிற விவரங்களையும் குறியீடுகளாக மாற்றி, அவற்றை மீண்டும் இணைக்கும் சாவியைத் தனியே வைத்தல். இது இன்னும் தனிப்பட்ட தரவுதான்.","also":["pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"தரவு செயலாக்க ஒப்பந்தம் (DPA)","text":"ஒரு சப்ளையர் உங்கள் சார்பாகத் தனிப்பட்ட தரவை எப்படிக் கையாளலாம் என்று சொல்லும் ஒப்பந்தம்.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"தரவுப் பாதுகாப்புத் தாக்க மதிப்பீடு (DPIA)","text":"தனிப்பட்ட தரவைப் பயன்படுத்தும் ஒரு திட்டம் மக்களை எப்படிப் பாதிக்கக்கூடும், அபாயங்களை எப்படிக் குறைப்பது என்பதைத் தொடங்கும் முன் செய்யும் கவனமான பார்வை.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"தணிக்கைப் பதிவு (ஆடிட் லாக்)","text":"யார் என்ன செய்தார், எப்போது என்ற பதிவு; அதனால் செயல்களைப் பின்னர் சரிபார்க்கலாம்.","also":["audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"இணக்கம் (கம்ப்ளையன்ஸ்)","text":"உங்களுக்குப் பொருந்தும் சட்டங்கள், விதிகள், தரநிலைகளைப் பின்பற்றுதல், அதைக் காட்டவும் முடிதல்.","also":["இணங்குதல்","compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"தகவல் பாதுகாப்பை நிர்வகிப்பதற்கான நன்கு அறியப்பட்ட சர்வதேசத் தரநிலை. நிறுவனங்கள் இதன்படி சான்றிதழ் பெறலாம்.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"ஒரு நிறுவனம் வாடிக்கையாளர் தரவை முறையாகப் பராமரிக்கிறது என்று காட்டும், வெளி தணிக்கையாளர்கள் சரிபார்த்த அமெரிக்க அறிக்கை.","also":["SOC2"]},{"id":"agent","g":"ai","word":"ஏஜென்ட்","text":"ஒரு பணியில் தானே வேலை செய்யும் AI: கோடைப் படித்து, மாற்றங்கள் செய்து, சரிபார்ப்புகளை ஓட்டி, தெரிவிக்கும். அதன் வேலையும் இன்னும் சரிபார்க்கப்படும்.","also":["ஏஜென்ட்கள்","agent","agents"]},{"id":"token","g":"ai","word":"டோக்கன்","text":"ஒவ்வொன்றும் ஒரு சொல்லின் சுமார் முக்கால் பங்கான, AI படிக்கும், எழுதும் சிறு எழுத்துத் துண்டுகள். AI பயன்பாடு டோக்கன்களில் கணக்கிடப்படும்; குறைவான டோக்கன்கள் என்றால் உங்கள் சந்தாவில் அதிகம் மீதமிருக்கும்.","also":["டோக்கன்கள்","token","tokens"]},{"id":"hook","g":"ai","word":"ஹூக்","text":"ஒரு AI செஷன் தொடங்கும்போது போல, குறிப்பிட்ட தருணத்தில் தானாக ஓடும் சிறு கட்டளை; அதனால் உங்கள் கருத்துகளை டீம் கேட்கும்.","also":["ஹூக்குகள்","hook","hooks"]},{"id":"ai","g":"ai","word":"செயற்கை நுண்ணறிவு (AI)","text":"எழுதுவது, கேள்விகளுக்குப் பதிலளிப்பது, படங்களை அடையாளம் காண்பது போல, பொதுவாக மனிதர் தேவை என்று நாம் நினைப்பவற்றைச் செய்யும் கணினி அமைப்புகள்.","also":["செயற்கை நுண்ணறிவு","AI","artificial intelligence","செயற்கை அறிவு"],"noTip":1},{"id":"ml","g":"ai","word":"இயந்திரக் கற்றல் (ML)","text":"கணினிகளுக்குச் சரியான விதிகளைக் கொடுப்பதற்குப் பதிலாக, நிறைய எடுத்துக்காட்டுகளிலிருந்து அமைப்புகளைக் கற்றுக்கொள்ள வைக்கும் முறை.","also":["ML","machine learning","மெஷின் லேர்னிங்"]},{"id":"model","g":"ai","word":"மாடல்","text":"ஒரு AI அமைப்பின் பயிற்றுவிக்கப்பட்ட “மூளை”; ஏராளமான எடுத்துக்காட்டுகளிலிருந்து கற்று உருவாக்கப்படுகிறது. மாடல்கள் திறமை, வேகம், விலையில் வேறுபடும்.","also":["மாடல்கள்","model","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"பெரிய மொழி மாடல் (LLM)","text":"மிகப் பெரிய அளவு எழுத்தில் பயிற்றுவிக்கப்பட்ட AI மாடல்; அதனால் மொழியைப் படிக்கவும் எழுதவும் முடியும்.","also":["LLM","LLMs","large language model"]},{"id":"genai","g":"ai","word":"உருவாக்கும் AI (ஜெனரேட்டிவ் AI)","text":"வகைப்படுத்துவது அல்லது கண்டறிவது மட்டுமல்லாமல், எழுத்து, படங்கள், கோடு போன்ற புதியவற்றை உருவாக்கும் AI.","also":["Generative AI","GenAI"]},{"id":"chatbot","g":"ai","word":"சாட்பாட்","text":"தட்டச்சு செய்தோ பேசியோ, அன்றாட மொழியில் நீங்கள் உரையாடும் புரோகிராம்.","also":["சாட்பாட்கள்","chatbot","chatbots"]},{"id":"prompt","g":"ai","word":"ப்ராம்ப்ட்","text":"நீங்கள் AI-க்குக் கொடுப்பது: உங்கள் கேள்வி அல்லது அறிவுறுத்தல்கள், கூடவே நீங்கள் ஒப்படைக்கும் எதுவும். தெளிவான ப்ராம்ப்ட்கள் பொதுவாக நல்ல பதில்களைப் பெறும்.","also":["ப்ராம்ப்ட்கள்","prompt","prompts"]},{"id":"prompteng","g":"ai","word":"ப்ராம்ப்ட் பொறியியல்","text":"நம்பகமான, பயனுள்ள முடிவுகளைத் தரும் ப்ராம்ப்ட்களை எழுதும் திறமை.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"சிஸ்டம் ப்ராம்ப்ட்","text":"உரையாடல் தொடங்கும் முன் AI-க்குக் கிடைக்கும், அதன் பங்கையும் விதிகளையும் நிர்ணயிக்கும் பின்னணி அறிவுறுத்தல்கள். நீங்கள் தட்டச்சு செய்வதை விட இவற்றுக்கு எடை அதிகம்.","also":["system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"கான்டெக்ஸ்ட் (பின்னணித் தகவல்)","text":"AI வேலை செய்யும்போது பார்க்கக்கூடிய எல்லாம்: அறிவுறுத்தல்கள், உங்கள் செய்திகள், அது படித்த கோப்புகள், முந்தைய பதில்கள்.","noTip":1},{"id":"ctxwin","g":"ai","word":"கான்டெக்ஸ்ட் விண்டோ","text":"டோக்கன்களில் அளக்கப்படும், AI ஒரே நேரத்தில் எவ்வளவை மனதில் வைத்திருக்க முடியும் என்பது. அதற்கு மேல் பழைய பகுதிகள் கைவிடப்படும் அல்லது சுருக்கப்படும்.","also":["context window","context windows"]},{"id":"session","g":"ai","word":"செஷன்","text":"தொடக்கம் முதல் முடிவு வரை, AI-யுடன் ஒரு வேலை உரையாடல். புதிய செஷன் புதிய நினைவுடன் தொடங்கும்.","also":["செஷன்கள்","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"நினைவு (மெமரி)","text":"உங்கள் விருப்பங்களையும் முந்தைய முடிவுகளையும் நினைவில் வைத்திருக்க, AI செஷன்களுக்கு இடையே வைத்திருக்கும் குறிப்புகள்.","noTip":1},{"id":"hallucination","g":"ai","word":"கற்பனைப் பதில் (ஹாலூசினேஷன்)","text":"AI உறுதியாகத் தோன்றும்படி ஒன்றைச் சொல்லும்போது அது கற்பனையாகவோ தவறாகவோ இருப்பது. முக்கியமான உண்மைகளைச் சரிபார்த்துக்கொள்ளுங்கள்.","also":["ஹாலூசினேஷன்","hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"பயிற்சி (ட்ரெய்னிங்)","text":"யாரும் பயன்படுத்தும் முன், ஒரு மாடலுக்கு ஏராளமான எடுத்துக்காட்டுகளைக் காட்டிக் கற்பித்தல்.","also":["பயிற்றுவித்தல்","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"பயிற்சித் தரவு","text":"ஒரு மாடல் கற்றுக்கொண்ட எடுத்துக்காட்டுகள். அதன் அறிவு அந்தத் தரவு சேகரிக்கப்பட்ட தேதியில் நின்றுவிடும்.","also":["training data","training set"]},{"id":"cutoff","g":"ai","word":"அறிவு எல்லைத் தேதி","text":"ஒரு AI-யின் உள்ளமைந்த அறிவு முடியும் தேதி. தேடிப் பார்க்காவிட்டால் அதற்குப் பிறகு நடந்தவை அதற்குத் தெரியாது.","also":["knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"நுண்ணிய மேம்பாடு (ஃபைன்-ட்யூனிங்)","text":"ஏற்கெனவே உள்ள மாடலை, ஒரு குறிப்பிட்ட வேலையில் சிறப்பாக்க, உங்கள் சொந்த எடுத்துக்காட்டுகளில் கூடுதலாகப் பயிற்றுவித்தல்.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"இன்ஃபரன்ஸ் (மாடல் பயன்பாடு)","text":"பயிற்றுவிக்கப்படுவதற்கு மாறாக, ஒரு AI மாடல் உண்மையில் எதற்காவது பதிலளிக்கப் பயன்படுத்தப்படுதல்.","also":["inference","model inference"]},{"id":"tooluse","g":"ai","word":"கருவிப் பயன்பாடு","text":"AI பேசுவது மட்டுமல்லாமல் செயல்களையும் செய்ய முடிவது: ஆப் அதற்குக் கொடுக்கும் கருவிகள் மூலம் கட்டளைகளை இயக்குவது, கோப்புகளைப் படிப்பது, இணையத்தில் தேடுவது.","also":["tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"துணை ஏஜென்ட்","text":"ஒரு முதன்மை AI சிறிய வேலையை ஒப்படைத்து, அதன் முடிவை மீண்டும் பெறும் உதவி AI.","also":["துணை ஏஜென்ட்கள்","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"பல-ஏஜென்ட்","text":"ஒரே வேலையில் பல AI-கள், ஒவ்வொன்றுக்கும் தன் பங்குடன், ஒரு சிறிய டீம் போல சேர்ந்து வேலை செய்வது.","also":["multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"தன்னாட்சி (ஆட்டானமி)","text":"ஒரு நபரிடம் கேட்க வேண்டிய நிலைக்கு வருவதற்கு முன், AI தானாக எவ்வளவு செய்ய அனுமதிக்கப்படுகிறது என்பது.","also":["autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"மனிதர் சுழற்சியில் (ஹ்யூமன் இன் தி லூப்)","text":"முக்கியமான கட்டங்களில் AI செய்வதைச் சரிபார்க்க அல்லது அங்கீகரிக்க ஒரு நபரை ஈடுபடுத்தி வைத்திருத்தல். AI-gile-இல் அது நீங்கள்தான்.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"பாதுகாப்புத் தடுப்புகள் (கார்ட்ரெயில்ஸ்)","text":"எதுவும் நேரலைக்குப் போகும் முன் ஒப்புதல் தேவைப்படுவது போல, AI-யின் செயல்களைப் பாதுகாப்பாக வைக்கும் எல்லைகளும் சரிபார்ப்புகளும். இவை தவறுகளின் அபாயத்தைக் குறைக்கும், ஆனால் முழுமையாக நீக்காது.","also":["guardrails","guardrail"]},{"id":"rag","g":"ai","word":"தேடி உருவாக்குதல் (RAG)","text":"AI பதிலளிக்கும் முன் உங்கள் சொந்த ஆவணங்களில் தேடிப் பார்க்க அனுமதித்தல்; அதனால் அதன் பதில்கள் உங்கள் உண்மைகளின் அடிப்படையில் அமையும்.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"எம்பெடிங்","text":"ஒத்த பொருள் உள்ளவற்றைக் கணினி கண்டுபிடிக்க, எழுத்தின் பொருளைப் பிடித்துக்கொள்ளும் எண்களின் பட்டியலாக அதை மாற்றுதல்.","also":["எம்பெடிங்குகள்","embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"வெக்டர் தரவுத்தளம்","text":"ஒத்த பொருள் உள்ளவற்றைக் கண்டுபிடிக்க, அந்த எண் பட்டியல்களை (embeddings) தேடுவதற்காகக் கட்டப்பட்ட தரவுத்தளம்.","also":["vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"AI ஆப்களில் கருவிகளையும் தரவு மூலங்களையும் இணைத்து, AI அவற்றைப் பயன்படுத்த உதவும் பொதுவான முறை.","also":["MCP"]},{"id":"temperature","g":"ai","word":"டெம்பரேச்சர் (வெப்பநிலை அமைப்பு)","text":"AI-யின் பதில்கள் எவ்வளவு துணிச்சலானவை என்பதற்கான அமைப்பு. குறைவாக இருந்தால் நிலையான, கணிக்கக்கூடிய பதில்கள்; அதிகமாக இருந்தால் பலவகைப் பதில்கள். எந்த அமைப்பும் அதை எப்போதும் சரியானதாக்காது.","also":["temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"பல-வகை உள்ளீடு (மல்டிமோடல்)","text":"எழுத்து, படங்கள், ஒலி போல, ஒரு வகைக்கு மேற்பட்ட தகவலுடன் வேலை செய்ய முடிவது.","also":["multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"AI மதிப்பீட்டுச் சோதனை (eval)","text":"தேர்ந்தெடுத்த எடுத்துக்காட்டுகளில் ஒரு AI எவ்வளவு நன்றாகச் செய்கிறது என்பதற்கான திட்டமிட்ட சோதனை; அதனால் மாடல்களையோ ப்ராம்ப்ட்களையோ ஒப்பிடலாம்.","also":["evaluation","eval","evals"]},{"id":"bias","g":"ai","word":"பாரபட்சம் (பயாஸ்)","text":"ஒரு AI (அல்லது மனிதர்) நியாயமற்ற முறையில் ஒரு பக்கம் சாய்வது, பெரும்பாலும் அது எதிலிருந்து கற்றதோ அதனால்.","also":["பயாஸ்","bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"பொறுப்பான AI","text":"முடிவுகளுக்கு மனிதர்களே பொறுப்பேற்கும் வகையில், AI-ஐ நியாயமாகவும் பாதுகாப்பாகவும் நேர்மையாகவும் பயன்படுத்துதல்.","also":["responsible AI","ethical AI","நெறிமுறை AI"]},{"id":"injection","g":"ai","word":"ப்ராம்ப்ட் இன்ஜெக்ஷன் (மறைமுக அறிவுறுத்தல் தந்திரம்)","text":"வலைப்பக்கம் அல்லது கோப்பில் மறைத்து வைத்த அறிவுறுத்தல்கள், பயனர் கேட்காத ஒன்றை AI செய்யும்படி முயலும் தந்திரம்.","also":["prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"கோரிக்கை வேக வரம்பு (ரேட் லிமிட்)","text":"குறிப்பிட்ட நேரத்தில் ஒரு சேவைக்கு எத்தனை கோரிக்கைகள் அனுப்பலாம் என்ற உச்சவரம்பு. அதைத் தாண்டினால் காத்திருக்க வேண்டும்.","also":["rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"பயன்பாட்டு வரம்பு","text":"ஒரு காலத்தில் உங்கள் சந்தாத் திட்டம் அனுமதிக்கும் AI வேலையின் அளவு; அதற்குப் பிறகு அது நிற்கும் அல்லது கூடுதல் செலவாகும்.","also":["usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"வைப் கோடிங்","text":"பெரும்பாலும் நீங்கள் விரும்புவதை AI-க்கு விவரித்து, கோடை அதையே எழுதவிடுவதன் மூலம் மென்பொருள் உருவாக்குதல்.","also":["vibe coding","vibe-coding"]},{"id":"budget","g":"money","word":"பட்ஜெட் (வரவு செலவுத் திட்டம்)","text":"ஒன்றுக்காக ஒதுக்கி வைத்த பணத்தின் அளவு.","also":["பட்ஜெட்","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"செலவு மதிப்பீடு","text":"நீங்கள் தொடங்கும் முன், ஒன்றுக்கு எவ்வளவு செலவாகும் என்பதற்கான சிறந்த ஊகம்.","also":["cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"முதலீட்டின் மீதான வருவாய் (ROI)","text":"நீங்கள் போட்டதுடன் ஒப்பிடும்போது திரும்பக் கிடைப்பது. நேர்மறையாக இருந்தால், அது மதிப்புள்ளதாக இருந்தது.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"மொத்த உடைமைச் செலவு (TCO)","text":"வாங்கும் விலை மட்டுமல்ல, இயக்குவது, ஆதரவு, மேம்படுத்தல்கள், இறுதியில் ஓய்வு கொடுப்பது உட்பட, ஒன்றின் முழு ஆயுளிலும் உண்மையில் ஆகும் எல்லாச் செலவும்.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx மற்றும் OpEx","text":"CapEx என்பது நீங்கள் வைத்திருக்கும் பொருட்களுக்காக முன்கூட்டியே செலவிடும் பணம்; OpEx என்பது மாதாந்திரக் கட்டணங்கள் போல தொடரும் செலவு.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"சந்தா","text":"ஒன்றைத் தொடர்ந்து பயன்படுத்த, பொதுவாக மாதம் அல்லது ஆண்டுக்கு, தவறாமல் பணம் செலுத்துதல்.","also":["சந்தாக்கள்","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"சேவையாக மென்பொருள் (SaaS)","text":"நீங்கள் இணையத்தில் பயன்படுத்தி, சந்தா மூலம் பணம் செலுத்தும் மென்பொருள்; தயாரிப்பாளரே அதை உங்களுக்காக இயக்குவார்.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"பயன்படுத்தியதற்கு மட்டும் கட்டணம்","text":"கிளவுட் கணினி அல்லது AI டோக்கன்கள் போல, நீங்கள் பயன்படுத்தியதற்கு மட்டும் பணம் செலுத்துதல்.","also":["pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"கூடுதல் பயன்பாடு (ஓவரேஜ்)","text":"உங்கள் சந்தாத் திட்டத்தில் சேர்க்கப்பட்டதை விட அதிகமாகப் பயன்படுத்துவது; அதற்குக் கூடுதல் செலவாகலாம்.","also":["overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"கட்டண எச்சரிக்கை","text":"செலவு அல்லது பயன்பாடு நீங்கள் தேர்ந்தெடுத்த அளவை அடையும்போது வரும் செய்தி. இது எச்சரிக்கும், ஆனால் மேலும் கட்டணங்களை எப்போதும் நிறுத்தாது.","also":["billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"இலவச நிலை","text":"கட்டணச் சேவையின் வரம்புகளுடன் கூடிய இலவச நிலை. தொடங்க வசதியானது.","also":["free tier","free plan","இலவசத் திட்டம்"]},{"id":"pricing","g":"money","word":"விலைத் திட்டம்","text":"ஒரு சேவை விற்கும் வெவ்வேறு தொகுப்புகள், ஒவ்வொன்றுக்கும் அதன் சொந்த விலையும் வரம்புகளும்.","also":["pricing plan","pricing plans","price plan","விலைத் திட்டங்கள்"]},{"id":"licence","g":"money","word":"உரிமம்","text":"மென்பொருள், எழுத்துருக்கள், படங்கள் போல வேறொருவர் உருவாக்கியதை நீங்கள் எப்படிப் பயன்படுத்தலாம், நகலெடுக்கலாம், மாற்றலாம் அல்லது பகிரலாம் என்பதற்கான விதிகள்.","also":["உரிமங்கள்","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"திறந்த மூலம் (ஓப்பன் சோர்ஸ்)","text":"அதன் உரிமத்தின் விதிகளுக்கு உட்பட்டு, எவரும் கோடைப் படிக்கவும் இலவசமாகப் பயன்படுத்தவும், பெரும்பாலும் மாற்றவும் முடிகிற மென்பொருள்.","also":["ஓப்பன் சோர்ஸ்","open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"திறந்த மூல உரிமம்","text":"திறந்த மூலக் கோடுடன் வரும் விதிகள். சில கிட்டத்தட்ட எதையும் செய்ய அனுமதிக்கும் (MIT போல); சில உங்கள் மாற்றங்களையும் பகிரச் சொல்லும் (GPL போல).","also":["திறந்த மூல உரிமங்கள்","open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"தனியுடைமை (புரோப்ரைட்டரி)","text":"ஒரு நிறுவனத்துக்குச் சொந்தமானது; நகலெடுக்கவோ மாற்றவோ சுதந்திரம் இல்லாதது. திறந்த மூலத்துக்கு எதிரானது.","also":["proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"பதிப்புரிமை","text":"கோடு, எழுத்து உட்பட தன் படைப்பின் நகல்களைக் கட்டுப்படுத்த ஒரு படைப்பாளிக்கு உள்ள சட்ட உரிமை.","also":["copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"அறிவுசார் சொத்து (IP)","text":"கோடு, வடிவமைப்புகள், பெயர்கள், லோகோக்கள் போல, சட்டம் உரிமை உள்ளதாகக் கருதும் எண்ணங்களும் படைப்புகளும்.","also":["அறிவுசார் சொத்து","IP","intellectual property"]},{"id":"tos","g":"money","word":"சேவை விதிமுறைகள்","text":"ஒரு சேவையைப் பயன்படுத்தும்போது நீங்கள் ஒப்புக்கொள்ளும் விதிகள்.","also":["பயன்பாட்டு விதிமுறைகள்","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"ஒப்பந்தம்","text":"சட்டம் ஆதரிக்கும், இரு தரப்புகளுக்கிடையிலான எழுத்து ஒப்புதல்.","also":["ஒப்பந்தங்கள்","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"பணி விவர அறிக்கை (SOW)","text":"என்ன வேலை செய்யப்படும், எப்போதுக்குள், எவ்வளவு பணத்துக்கு என்று சரியாகக் கூறும் ஆவணம்.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"நிலையான விலை","text":"எவ்வளவு நேரம் ஆனாலும், முழு வேலைக்கும் ஒப்புக்கொண்ட ஒரே விலை.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"நேரமும் பொருட்களும் (டைம் அண்ட் மெட்டீரியல்ஸ்)","text":"நிர்ணயித்த விலைக்குப் பதிலாக, உண்மையில் வேலை செய்த மணிநேரங்களுக்கும் உண்மையில் பயன்படுத்தியவற்றுக்கும் பணம் செலுத்துதல்.","also":["time and materials","T&M"]},{"id":"invoice","g":"money","word":"விலைப்பட்டியல் (இன்வாய்ஸ்)","text":"செய்த வேலைக்கு அல்லது வழங்கிய பொருட்களுக்குப் பணம் கேட்கும் பில்.","also":["இன்வாய்ஸ்","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"வழங்குநரில் சிக்கிக்கொள்ளுதல் (வெண்டர் லாக்-இன்)","text":"ஒரு சப்ளையரிடமிருந்து விலகுவது மிகக் கடினமாக அல்லது செலவாக இருப்பதால் அவருடனேயே சிக்கிக்கொள்ளும் நிலை.","also":["vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"கொள்முதல்","text":"சப்ளையர்களிடமிருந்து தேர்ந்தெடுத்து வாங்கும் செயல்முறை.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"சேவை ஈடு (சர்வீஸ் கிரெடிட்)","text":"ஒரு சப்ளையர் தன் SLA-வை எட்டத் தவறும்போது உங்களுக்குக் கிடைக்கும் பணத் திரும்பல் அல்லது தள்ளுபடி.","also":["service credit","service credits"]}]}};
